INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('fca00a31-190c-566b-a4a3-fca95768007e', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 26, 26, 'ቅዱስና ፡ የታመነ ፡ ወዳጅህ ፡ ሙሴንም ፡ እንደዚሁ ፡ በቍጥቋጦው ፡ ዘንድ ፡ እኔ ፡ ከዓለም ፡ በፊት ፡ የነበርኩ ፡ ነኝ ፣ ፡ ስሜም ፡ እስከ ፡ ዘለዓለም ፡ ይኖራል ፡ አልከው ።'),
  ('c3e256a5-8e6c-5a97-a47e-799b827d0a4b', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 27, 27, 'አንተ ፡ ግን ፡ ለዘለዓለም ፡ ትኖራለህ ፣ መታሰብም ፡ ለልጅ ፡ ልጅ ፡ ነው ። የአብርሃም ፡ ልጆችም ፡ እስከ ፡ ዘለዓለም ፡ የተባረኩ ፡ ይሆኑ ፡ ዘንድ ፡ ባርክ ።'),
  ('a2f71f7a-217f-5bdd-a035-a110c2dcccdd', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 28, 28, 'ሰውን ፡ የሚናገር ፡ ይሆን ፡ ዘንድ ፡ ፈጠርከው ፣ ፡ ሰውንም ፡ በመልካችንንና ፡ በምሳሌያችን ፡ እንፍጠር ፡ ብለህ ፡ በጥበብህ ፡ ተናገርክ ፣ ፡ አዳምንም ፡ በሁሉ ፡ ላይ ፡ መስፍን ፡ አድርገህ ፡ ሾምከው ፣ ፡ የዘለዓለም ፡ ሕይወትም ፡ ሰጠኸው ።'),
  ('f5f54e62-649f-5b7c-aa8f-d828ff0c33d6', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 29, 29, 'ትእዛዝህንም ፡ በአፈረሰ ፡ ጊዜ ፡ ከገነት ፡ አውጥተህ ፡ በእርሱ ፡ ላይ ፡ ሞትን ፡ አመጣህ ።'),
  ('8ef764c1-93e5-594b-aae6-5746f0f1d8c5', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 30, 30, 'ከዚህም ፡ በኋላ ፡ አንድ ፡ ልጅህን ፡ ልከህ ፡ ከውድቀቱ ፡ አነሣኸው ፣ ፡ ደስታ ፡ ወደ ፡ አለበት ፡ ገነትም ፡ መለስከው ።'),
  ('b0268dfc-e192-5adc-af14-409b888ead69', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 31, 31, 'እግዚአብሔር ፡ ገናና ፡ ኃይለኛ ፡ የምታስፈራ ፡ የምትምር ፡ የዋህ ፣ ፡ ሁሉን ፡ የያዝህ ፣ ፡ ድንቅን ፡ የምትሠራ ፣ ፡ ከሥራውና ፡ ከፍጥረቱ ፡ ሁሉ ፡ ላይ ፡ ይቅርታህንም ፡ የማታርቅ ፣ ፡ ቸርና ፡ ሰውን ፡ የምትወድ ፡ አንተ ፡ ብቻ ፡ ነህ ።'),
  ('ac4fd00f-1072-53c6-ad56-bcce53570763', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 32, 32, 'ኃጥአንን ፡ የዋህን ፡ ታደርጋሕን ፡ በቸርነትህም ፡ ብዛት ፡ ትመልሳቸዋለህ ።'),
  ('96112706-6215-5ae2-a121-5643004d890c', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 33, 33, 'እኛም ፡ ወደ ፡ አንተ ፡ አንጋጠን ፡ ዓይኖቻችነን ፡ ወደ ፡ ሰማይ ፡ አቅንተን ፡ እንመለከት ፡ ዘንድ ፡ ሳይገባን ፡ አንተ ፡ በኃይልህ ፡ ጽናት ፡ መዋረዳችንን ፡ ትመለከታለህ ።'),
  ('53107335-e375-5aa5-a0e2-62bef9bba041', '5ceb1917-f1c6-59d3-a851-400f7a2fac10', '2f9a531a-fcf8-5767-af50-8a2c2c04e141', 34, 34, 'ሰማይ ፡ በትእዛዝህ ፡ የተሰቀለ ፡ ነው ። ምድርም ፡ በቃልህ ፡ ጸናች ፣ ፡ ጌታ ፡ ሆይ ፡ አንተ ፡ ኃይለኛ ፡ ነህና ፣ ፡ ፍርድህም ፡ እውነት ፡ ነውና ፡ የፈጠርከው ፡ ምድርን ፡ መላ ።'),
  ('28a2ba01-f5c7-528f-a9b5-fc9f1befe125', '31e469f7-bd0c-50aa-a5e4-e7af51c7ed4f', 'cda1d8ad-8904-5659-a66d-66a09d5f6b1c', 1, 1, 'የእሳት ፡ ነበልባል ፡ የሆኑ ፡ የረቂቃን ፡ መላእክት ፡ ሠራዊት ፡ ሁሉ ፡ ክንፎቻቸው ፡ ስድስት ፡ የሚሆኑ ፡ ሱራፌልና ፡ ኪሩበልም ፡ በታላቅ ፡ ቃል ፡ አንተን ፡ ያመሰግናሉ ፣ ፡ ዝም ፡ በማይል ፡ ቃልም ፡ ይዘምራሉ ፣ ፡ ቅዱስ ፡ ቅዱስ ፡ ቅዱስ ፡ ፍጹም ፡ የሠራዊት ፡ ጌታ ፡ የጌትነትህ ፡ ምስጋና ፡ ሰማያትንና ፡ ምድርን ፡ የመላ ፡ ነው ፡ ይላሉ ።'),
  ('1bd73219-83ba-59c9-a1dc-561dd9f8b14a', '31e469f7-bd0c-50aa-a5e4-e7af51c7ed4f', 'cda1d8ad-8904-5659-a66d-66a09d5f6b1c', 2, 2, 'የእነዚያም ፡ መላእክትና ፡ የመላእክት ፡ አለቆች ፡ ቁጥራቸው ፡ የወገን ፡ ስማቸው ፡ መላእክት ፡ መናብርት ፡ ሥልጣናት ፡ አጋዕዝት ፡ ኃይላት ፡ ሊቃናት ፡ ኪሩቤል ፡ ሱራፌል ፡ ይባላሉ ፣ ፡ እየጮሁም ፡ የእስራኤል ፡ ፈጣሪ ፡ እግዚአብሔር ፡ ይመስገን ፡ ከአሕብ ፡ ወገን ፡ የምትሆን ፡ ቡርክት ፡ ቤተ ፡ ክርስቲያንም ፡ የሰማያት ፡ መላእክት ፡ ኃይልን ፡ ትመስላለች ፡ ይላሉ ፡ ሌሊትና ፡ ቀንም ፡ በልዩ ፡ ሰውነት ፡ በንጹሕ ፡ ልቡና ፡ እንዲህ ፡ እያሉ ፡ ያመሰግናሉ ።'),
  ('e3c38297-29cb-5d81-a5c8-5e9c0c659305', '31e469f7-bd0c-50aa-a5e4-e7af51c7ed4f', 'cda1d8ad-8904-5659-a66d-66a09d5f6b1c', 3, 3, 'የእግዚአብሔር ፡ ሠረገላው ፡ እልፍ ፡ አእላፋት ፡ የአእላፋት ፡ ትእልፊት ፡ በቅዱስ ፡ የሲና ፡ ተራራ ፡ እግዚአብሔርን ፡ ያመሰግኑታል ፣ ፡ ሰማያትና ፡ በውስጣቸው ፡ ያለው ፡ ሁሉ ፡ አንተን ፡ ያመሰግናሉ ።'),
  ('2b93e111-c22e-50d8-ac7b-6613aef7137c', '31e469f7-bd0c-50aa-a5e4-e7af51c7ed4f', 'cda1d8ad-8904-5659-a66d-66a09d5f6b1c', 4, 4, 'አንተ ፡ ሰማይን ፡ እንደ ፡ ዋልታ ፡ ሰቅለኸዋልና ፡ ምድርንም ፡ መሠረትሃት ፡ በውሃም ፡ ላይ ፡ አጽንተሃታልና ።'),
