  ('30957266-9fc7-5d29-a995-3595193d406e', '31e469f7-bd0c-50aa-a5e4-e7af51c7ed4f', 'cda1d8ad-8904-5659-a66d-66a09d5f6b1c', 6, 6, 'ስለዚህም ፡ ነገር ፡ የሰው ፡ ፍጥረት ፡ ሁሉ ፡ ክብርንና ፡ ምስጋናን ፡ መሥዋዕትን ፣ ፡ ቍርባንን ፣ ፡ ዕጣንንም ፡ በአንድ ፡ ልጅህ ፡ በጌታችንና ፡ በመድኃኒታችን ፡ በኢየሱስ ፡ ክርስቶስ ፡ ለአንተ ፡ ያሳርጉ ፡ ዘንድ ፡ አገባብ ፡ ነው ።'),
  ('ff815b8e-61b6-59db-ada5-44c782bc8547', '31e469f7-bd0c-50aa-a5e4-e7af51c7ed4f', 'cda1d8ad-8904-5659-a66d-66a09d5f6b1c', 7, 7, 'ሁሉን ፡ የፈጠርክ ፡ ቸር ፡ ሰው ፡ ወዳጅ ፡ በጎ ፡ ነገርን ፡ የምታደርግ ፡ አንተ ፡ ብቻ ፡ ነህ ፣ ፡ ለአንተ ፡ ክብርና ፡ ሥልጣን ፡ ይገባል ፡ ለዘለዓለሙ ፡ አሜን ።'),
  ('6b5e48a8-cdd4-59e8-a458-dbaa08dd5a4e', '31e469f7-bd0c-50aa-a5e4-e7af51c7ed4f', 'cda1d8ad-8904-5659-a66d-66a09d5f6b1c', 8, 8, 'በሰማይ ፡ አንተ ፡ ነህ ፣ ፡ ምድርም ፡ አንተ ፡ ነህ ፣ ፡ በባሕርም ፡ አንተ ፡ ነህ ፣ ፡ ፍጥረትን ፡ ሁሉ ፡ ከምድር ፡ ዳርቻዎች ፡ የምትሰበስባቸው ፡ አንተ ፡ ነህ ፣ ፡ ለገናንነትህ ፡ ፍጻሜ ፡ የለውም ።'),
