  ('9941c3db-7627-5dbf-a3d4-1a38985d5f87', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 7, 7, 'በእስምርናስም ፡ መጀመሪያ ፡ አርስጦስ ፣ ፡ ከእሱም ፡ በኋላ ፡ የሉይስ ፡ ወገን ፡ እስተራቴዎስ ፣ ፡ ከእሱም ፡ ቀጥሎ ፡ አርስጦን ።'),
  ('789b4939-c4c5-525e-a90e-5c457ca3c424', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 8, 8, 'በበርጋሞስም ፡ መጀመሪያ ፡ የተሾመ ፡ ጋይዮስ ።'),
  ('4a86193f-4052-58a2-a99a-3a51952730b8', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 9, 9, 'በፊልድልፍያም ፡ መጀመሪያ ፡ በጴጥሮስ ፡ ዘንድ ፡ የተሾመ ፡ ድሜጥሮስ ።'),
  ('30e93460-c433-541e-a7bb-fd4991c81f82', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 10, 10, 'በክንክራኦስም ፡ መጀመሪያ ፡ በጳውሎስ ፡ ዘንድ ፡ የተሾመ ፡ ሉኪዮስ ።'),
  ('fdd250cb-608b-57e4-a73d-70431a858e7b', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 11, 11, 'በቀርጤስም ፡ ቲቶ ።'),
  ('6250ff8d-056b-5b4d-abed-a7feca7024c4', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 12, 12, 'በአቴናም ፡ ዲዮናስዮስ ።'),
  ('6ccc3479-19ff-55aa-ace0-9fe6b996efc9', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 13, 13, 'በጥሪጶሊፎኒቅያም ፡ ማራሶን ።'),
  ('b17ff12d-1b1e-5578-ab19-935d1266bd79', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 14, 14, 'በሎዶቅያም ፡ አርካቦስ ።'),
  ('bba6766c-c8e5-52d8-a875-73c2cbf6293f', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 15, 15, 'በቈላስይስም ፡ ፊልሞና ።'),
  ('1437a3d3-bbba-5f67-ac3e-edb36a8857db', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 16, 16, 'በመቄዶንያና ፡ በሲርያሶን ፡ የፊልሞና ፡ ወገን ፡ አናሲሞስ ።'),
  ('05cd89cc-41a8-5d71-af5a-524f8d69450e', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 17, 17, 'በገላትያ ፡ ቤተ ፡ ክርስቲያን ፡ ክሪስኪስ ።'),
  ('74e3283b-e529-5fcf-ad43-9627538aa66f', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 18, 18, 'በእስያ ፡ ሀገር ፡ አቂላና ፡ ንኪትስ ።'),
  ('6dd78f19-8b78-5890-a0af-c63424f6f710', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 19, 19, 'በኤጌና ፡ ቤተ ፡ ክርስቲያንም ፡ ቅርስጶስ ።'),
  ('0edc023b-5f5e-5b49-ab09-2dd3f801a524', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 20, 20, 'በኢየሩሳሌም ፡ አምነን ፡ የሾምናቸው ፡ በያገራቸው ፡ ይሰብኩ ፡ ያስተምሩ ፡ ዘንድ ፡ የላክናቸው ፡ እሊህ ፡ ናቸው ።'),
  ('51e8284d-3741-501f-ae2b-76c02532800f', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 21, 21, 'የእነዚህን ፡ ድካማቸውን ፡ አስቡ ። ምክራቸውንም ፡ ተቀበሉ ፣ ፡ ቃላቸውንም ፡ ጠብቁ ። እግዚአብሔር ፡ ከእናንተ ፡ ጋር ፡ ይሁን ፣ ፡ ከዛሬ ፡ ጀምሮ ፡ እስከ ፡ ዘለዓለሙ ።'),
  ('dda5d029-208c-52af-aa67-acb9e33fec99', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 22, 22, 'ወደ ፡ ሰማይ ፡ ወደ ፡ አብ ፡ በዓረገ ፡ ጊዜ ፡ ዓለም ፡ እስኪያልፍ ፡ ድረስ ፡ በዘመኑ ፡ ሁሉ ፡ እኔ ፡ ከእናንተ ፡ ጋራ ፡ ነኝ ፡ እንዳለን ።'),
  ('7001a57d-ee7f-5b06-a68e-f3b10455663a', '9ec797ae-7e92-5891-a4d9-1feda7011826', '5d7fd17a-ac00-5008-ad30-b48a91b8a409', 23, 23, 'ጌትነትና ፡ ክብር ፡ ለዘለዓለሙ ፡ የእርሱ ፡ ገንዘብ ፡ ለሆነ ፡ ለእግዚአብሔር ፡ ምስጋና ፡ ይግባው ፡ አሜን ፡ አሜን ፡ ይሁን ፡ ይሁን ።'),
  ('ae207259-cfd4-5bb9-a016-106bc28b1156', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 1, 1, 'In the beginning God created the heavens and the earth.'),
  ('cc363d39-9beb-5cff-aa57-e0d55515ebca', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 2, 2, 'Now the earth was formless and empty. Darkness was on the surface of the deep. God''s Spirit was hovering over the surface of the waters.'),
  ('c5f722f5-03a2-5f0e-a129-cb63cd4b978f', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 3, 3, 'God said, "Let there be light," and there was light.'),
  ('27df941c-8fa2-58c0-a9ab-af4aff267d00', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 4, 4, 'God saw the light, and saw that it was good. God divided the light from the darkness.'),
  ('c9d1bb75-d95c-5835-a29b-4f70571c8fb2', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 5, 5, 'God called the light "day," and the darkness he called "night." There was evening and there was morning, one day.'),
  ('7b6301c7-0cf2-5772-a983-ec3c9f23d595', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 6, 6, 'God said, "Let there be an expanse in the middle of the waters, and let it divide the waters from the waters."'),
  ('efdf9d3e-b276-5079-a08d-9b1c3f6be755', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 7, 7, 'God made the expanse, and divided the waters which were under the expanse from the waters which were above the expanse; and it was so.'),
  ('a6955691-4ec4-5da0-a28c-d7fb38c33f94', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 8, 8, 'God called the expanse "sky." There was evening and there was morning, a second day.'),
  ('84693de3-b084-58fc-a383-36f211e4a055', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 9, 9, 'God said, "Let the waters under the sky be gathered together to one place, and let the dry land appear;" and it was so.'),
  ('322a6245-390d-5d6b-ad62-0330da773130', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 10, 10, 'God called the dry land "earth," and the gathering together of the waters he called "seas." God saw that it was good.'),
  ('0c779c34-a91a-51cf-ae23-9f8fae48d66d', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 11, 11, 'God said, "Let the earth put forth grass, herbs yielding seed, and fruit trees bearing fruit after their kind, with its seed in it, on the earth;" and it was so.'),
  ('0e60c74e-c155-54a9-a765-d54acaab3a8d', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 12, 12, 'The earth brought forth grass, herbs yielding seed after their kind, and trees bearing fruit, with its seed in it, after their kind; and God saw that it was good.'),
  ('177d79f6-e178-5471-af14-70429d6cd207', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 13, 13, 'There was evening and there was morning, a third day.'),
  ('307e69bb-2c47-593a-aae7-c14171466a1d', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 14, 14, 'God said, "Let there be lights in the expanse of sky to divide the day from the night; and let them be for signs, and for seasons, and for days and years;'),
  ('1f3ce231-f815-5a61-a292-175b3d1c5481', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 15, 15, 'and let them be for lights in the expanse of sky to give light on the earth;" and it was so.'),
  ('fdf143c8-8390-557f-a245-99c2ebb48a02', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 16, 16, 'God made the two great lights: the greater light to rule the day, and the lesser light to rule the night. He also made the stars.'),
  ('f9edd5ed-6e9d-5856-a4c1-cccda81a5691', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 17, 17, 'God set them in the expanse of sky to give light to the earth,'),
  ('daf05830-430a-520d-ab9e-7a3a83a5ab43', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 18, 18, 'and to rule over the day and over the night, and to divide the light from the darkness. God saw that it was good.'),
  ('c425cd71-fc01-5af5-a605-17c78927a210', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 19, 19, 'There was evening and there was morning, a fourth day.'),
  ('5b079b7b-8643-51e0-abc8-fbb0bc92fa7b', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 20, 20, 'God said, "Let the waters swarm with swarms of living creatures, and let birds fly above the earth in the open expanse of sky."'),
  ('365c9931-80b0-5748-a936-b507e25ed6c5', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 21, 21, 'God created the large sea creatures, and every living creature that moves, with which the waters swarmed, after their kind, and every winged bird after its kind. God saw that it was good.'),
  ('bd80c2e6-21a2-52cf-a241-1dfe877a7c57', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 22, 22, 'God blessed them, saying, "Be fruitful, and multiply, and fill the waters in the seas, and let birds multiply on the earth."'),
  ('375bc2f9-9c05-52ee-a5bb-27cf14bf6ab3', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 23, 23, 'There was evening and there was morning, a fifth day.'),
  ('d9b98e64-0c47-5d31-ae69-cc3eca278e6a', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 24, 24, 'God said, "Let the earth bring forth living creatures after their kind, livestock, creeping things, and animals of the earth after their kind;" and it was so.'),
  ('dc90080b-c354-5e49-aea4-70ade85d176b', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 25, 25, 'God made the animals of the earth after their kind, and the livestock after their kind, and everything that creeps on the ground after its kind. God saw that it was good.'),
  ('99bacd46-267f-52ab-aeca-783610e138f4', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 26, 26, 'God said, "Let us make man in our image, after our likeness: and let them have dominion over the fish of the sea, and over the birds of the sky, and over the livestock, and over all the earth, and over every creeping thing that creeps on the earth."'),
  ('6eac86b5-bf03-5956-aecc-80b06e9d6918', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 27, 27, 'God created man in his own image. In God''s image he created him; male and female he created them.'),
  ('ee9328aa-b818-5033-a2e8-2132e8e70172', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 28, 28, 'God blessed them. God said to them, "Be fruitful, multiply, fill the earth, and subdue it. Have dominion over the fish of the sea, over the birds of the sky, and over every living thing that moves on the earth."'),
  ('228169d7-0528-5fdc-a261-e5e1c876c553', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 29, 29, 'God said, "Behold, I have given you every herb yielding seed, which is on the surface of all the earth, and every tree, which bears fruit yielding seed. It will be your food.'),
  ('fe5bb9e7-0862-5fd9-a3e1-5d59a3c2fa7a', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 30, 30, 'To every animal of the earth, and to every bird of the sky, and to everything that creeps on the earth, in which there is life, I have given every green herb for food;" and it was so.'),
  ('2eb562f2-3e6c-5399-ae57-837ca6897dd2', 'aa183a7b-7187-5000-a7c1-70c72b8288ac', NULL, 31, 31, 'God saw everything that he had made, and, behold, it was very good. There was evening and there was morning, a sixth day.'),
  ('3fdd9cf9-2795-58b6-a479-f1f09f0b3644', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 1, 1, 'The heavens and the earth were finished, and all their vast array.'),
  ('4c6de7ac-ca5b-5f74-a241-dd503ae88046', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 2, 2, 'On the seventh day God finished his work which he had made; and he rested on the seventh day from all his work which he had made.'),
  ('ea75aec8-b7d8-535f-a94a-60ab3c0a5596', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 3, 3, 'God blessed the seventh day, and made it holy, because he rested in it from all his work which he had created and made.'),
  ('672bb461-527b-58c8-ae6e-cdac2a5b7f57', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 4, 4, 'This is the history of the generations of the heavens and of the earth when they were created, in the day that Yahweh God made the earth and the heavens.'),
  ('f6e85749-174f-5bf2-a9d0-f6a5f76c6000', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 5, 5, 'No plant of the field was yet in the earth, and no herb of the field had yet sprung up; for Yahweh God had not caused it to rain on the earth. There was not a man to till the ground,'),
  ('e9dfc58d-c52a-5b59-a2e5-797c3acb03f4', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 6, 6, 'but a mist went up from the earth, and watered the whole surface of the ground.'),
  ('68c6601a-1c36-5a10-ab14-669aaf77462f', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 7, 7, 'Yahweh God formed man from the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul.'),
  ('de3acab6-4450-5f05-a3eb-c3469320ea87', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 8, 8, 'Yahweh God planted a garden eastward, in Eden, and there he put the man whom he had formed.'),
  ('add5ae3f-f09a-5b75-a4cb-01d4446f882f', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 9, 9, 'Out of the ground Yahweh God made every tree to grow that is pleasant to the sight, and good for food; the tree of life also in the middle of the garden, and the tree of the knowledge of good and evil.'),
  ('3436eb58-bb29-5934-ad76-d3d10e73c656', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 10, 10, 'A river went out of Eden to water the garden; and from there it was parted, and became four heads.'),
  ('c5d95a76-2445-5d51-a935-90ecf3d0c0b0', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 11, 11, 'The name of the first is Pishon: this is the one which flows through the whole land of Havilah, where there is gold;'),
  ('eccebda2-fdab-5e26-a4e5-27de73eea0b3', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 12, 12, 'and the gold of that land is good. There is aromatic resin and the onyx stone.'),
  ('1f44b464-d0a5-507f-a58f-6a3826ebb185', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 13, 13, 'The name of the second river is Gihon: the same river that flows through the whole land of Cush.'),
  ('17d77504-ffa0-5c99-a1f6-03edecae8b5c', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 14, 14, 'The name of the third river is Hiddekel: this is the one which flows in front of Assyria. The fourth river is the Euphrates.'),
  ('f3795437-0dba-5e12-a4c1-f1221f977ab0', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 15, 15, 'Yahweh God took the man, and put him into the garden of Eden to dress it and to keep it.'),
  ('9d913a8b-8115-5799-ae48-743ebdb79a33', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 16, 16, 'Yahweh God commanded the man, saying, "Of every tree of the garden you may freely eat;'),
  ('8078f231-28fc-53ac-aa67-dadbf1925eaa', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 17, 17, 'but of the tree of the knowledge of good and evil, you shall not eat of it; for in the day that you eat of it you will surely die."'),
  ('eefdf52b-20e2-57a0-aa8d-8447b67ac595', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 18, 18, 'Yahweh God said, "It is not good that the man should be alone; I will make him a helper suitable for him."'),
  ('eee4e291-236f-5974-a280-c49d1824b5a7', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 19, 19, 'Out of the ground Yahweh God formed every animal of the field, and every bird of the sky, and brought them to the man to see what he would call them. Whatever the man called every living creature, that was its name.'),
  ('e5364748-5a95-553a-ac54-bf02c0c59c51', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 20, 20, 'The man gave names to all livestock, and to the birds of the sky, and to every animal of the field; but for man there was not found a helper suitable for him.'),
  ('c3adfa57-fd17-5b38-a831-b57b34759b20', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 21, 21, 'Yahweh God caused a deep sleep to fall on the man, and he slept; and he took one of his ribs, and closed up the flesh in its place.'),
  ('6aa87339-84d6-56ba-abdf-66a6cb536d53', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 22, 22, 'He made the rib, which Yahweh God had taken from the man, into a woman, and brought her to the man.'),
  ('9f759ea9-308e-5fa8-a5e0-58659ca2c70c', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 23, 23, 'The man said, "This is now bone of my bones, and flesh of my flesh. She will be called ''woman,'' because she was taken out of Man."'),
  ('24aa65d7-41bc-5a66-a33f-216a6a0f3949', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 24, 24, 'Therefore a man will leave his father and his mother, and will join with his wife, and they will be one flesh.'),
  ('60643c09-a1dc-5a64-aa04-87d140efa121', '1e2a5b24-6f89-55d5-a772-3ed2a7d246b4', NULL, 25, 25, 'They were both naked, the man and his wife, and were not ashamed.'),
  ('b4d47d11-408c-5e4c-aaf2-1c611ece638c', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 1, 1, 'Now the serpent was more subtle than any animal of the field which Yahweh God had made. He said to the woman, "Has God really said, ''You shall not eat of any tree of the garden?''"'),
  ('a6f4fc09-1d03-558e-ac3d-d1206e0f5b96', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 2, 2, 'The woman said to the serpent, "Of the fruit of the trees of the garden we may eat,'),
  ('84f265d9-257b-5570-a187-44b3bf3e5baf', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 3, 3, 'but of the fruit of the tree which is in the middle of the garden, God has said, ''You shall not eat of it, neither shall you touch it, lest you die.''"'),
  ('9912fd72-b19a-5f93-a029-82220ff16da3', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 4, 4, 'The serpent said to the woman, "You won''t surely die,'),
  ('d680e956-b495-5455-a507-64c5e2fbcee1', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 5, 5, 'for God knows that in the day you eat it, your eyes will be opened, and you will be like God, knowing good and evil."'),
  ('f9357452-22b4-58d8-ac80-d39e3b0aed87', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 6, 6, 'When the woman saw that the tree was good for food, and that it was a delight to the eyes, and that the tree was to be desired to make one wise, she took of its fruit, and ate; and she gave some to her husband with her, and he ate.'),
  ('507e35d1-f314-5c2c-a0c5-acbcb3f9cb79', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 7, 7, 'The eyes of both of them were opened, and they knew that they were naked. They sewed fig leaves together, and made themselves aprons.'),
  ('0ca39db8-7728-5131-a827-ef0543862c64', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 8, 8, 'They heard the voice of Yahweh God walking in the garden in the cool of the day, and the man and his wife hid themselves from the presence of Yahweh God among the trees of the garden.'),
  ('6e5a2d7d-bcec-5b93-a8cb-b42eecc20434', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 9, 9, 'Yahweh God called to the man, and said to him, "Where are you?"'),
  ('221f1e88-5798-5d22-a38d-f5db89bf5453', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 10, 10, 'The man said, "I heard your voice in the garden, and I was afraid, because I was naked; and I hid myself."'),
  ('44b17f6e-d501-585a-ab3c-f75649db4591', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 11, 11, 'God said, "Who told you that you were naked? Have you eaten from the tree that I commanded you not to eat from?"'),
  ('e3917983-543d-57df-a8b4-74c6572a66c4', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 12, 12, 'The man said, "The woman whom you gave to be with me, she gave me of the tree, and I ate."'),
  ('04582d6b-2302-5c79-aeda-d8c1ab3b9924', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 13, 13, 'Yahweh God said to the woman, "What is this you have done?" The woman said, "The serpent deceived me, and I ate."'),
  ('c7802631-1914-5919-a93e-2f3fd1b81037', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 14, 14, 'Yahweh God said to the serpent, "Because you have done this, you are cursed above all livestock, and above every animal of the field. On your belly you shall go, and you shall eat dust all the days of your life.'),
  ('ba001049-753c-5327-a876-1663d66fb170', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 15, 15, 'I will put enmity between you and the woman, and between your offspring and her offspring. He will bruise your head, and you will bruise his heel."'),
  ('83ba24c9-ecee-5b53-ae56-b2f94c1ffc14', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 16, 16, 'To the woman he said, "I will greatly multiply your pain in childbirth. In pain you will bring forth children. Your desire will be for your husband, and he will rule over you."'),
  ('5e272157-4098-5f12-a225-ad9ff556c45d', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 17, 17, 'To Adam he said, "Because you have listened to your wife''s voice, and have eaten of the tree, of which I commanded you, saying, ''You shall not eat of it,'' cursed is the ground for your sake. In toil you will eat of it all the days of your life.'),
  ('a7f8d9fe-7e2a-535b-ae6b-d03124115b19', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 18, 18, 'Thorns also and thistles will it bring forth to you; and you will eat the herb of the field.'),
  ('fec6b846-d77e-56d6-aa66-17689ce38e78', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 19, 19, 'By the sweat of your face will you eat bread until you return to the ground, for out of it you were taken. For you are dust, and to dust you shall return."'),
  ('b34b1a76-fa2f-5744-a9a2-380c6fb66ae1', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 20, 20, 'The man called his wife Eve, because she was the mother of all living.'),
  ('829a3cda-8c0c-5dd5-a5b4-13d669b3e28f', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 21, 21, 'Yahweh God made coats of skins for Adam and for his wife, and clothed them.'),
  ('5cd091a9-b919-5181-ac0f-e9a59cf4b6e7', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 22, 22, 'Yahweh God said, "Behold, the man has become like one of us, knowing good and evil. Now, lest he put forth his hand, and also take of the tree of life, and eat, and live forever..."'),
  ('033cb07e-8eed-5410-a3a8-57c9a80adcc6', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 23, 23, 'Therefore Yahweh God sent him forth from the garden of Eden, to till the ground from which he was taken.'),
  ('6a0bc7ea-a80b-5f14-af93-82b1ac7333de', '794f44fe-a388-5637-a606-fe16539f19ad', NULL, 24, 24, 'So he drove out the man; and he placed Cherubs at the east of the garden of Eden, and the flame of a sword which turned every way, to guard the way to the tree of life.'),
  ('8cf9d560-80d3-548b-a9f2-e2d66b806876', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 1, 1, 'The man knew Eve his wife. She conceived, and gave birth to Cain, and said, "I have gotten a man with Yahweh''s help."'),
  ('60c9a52e-dfdc-5bfc-afca-a4f50a27a2e7', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 2, 2, 'Again she gave birth, to Cain''s brother Abel. Abel was a keeper of sheep, but Cain was a tiller of the ground.'),
  ('846881a0-cd6f-545e-af45-6c0507c6a573', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 3, 3, 'As time passed, it happened that Cain brought an offering to Yahweh from the fruit of the ground.'),
  ('54a3b6aa-d0f7-5556-a7e0-c0fdee22c4b9', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 4, 4, 'Abel also brought some of the firstborn of his flock and of its fat. Yahweh respected Abel and his offering,'),
  ('59a6acb7-1c37-5845-a05d-16c9feec5ff0', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 5, 5, 'but he didn''t respect Cain and his offering. Cain was very angry, and the expression on his face fell.'),
  ('b595f392-07be-548f-a227-cdfd511cd01a', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 6, 6, 'Yahweh said to Cain, "Why are you angry? Why has the expression of your face fallen?'),
  ('7cd884f2-b2bb-55d0-ace2-d394e864e644', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 7, 7, 'If you do well, will it not be lifted up? If you don''t do well, sin crouches at the door. Its desire is for you, but you are to rule over it."'),
  ('34a4f719-e6fa-5ead-a137-1232b2746a7d', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 8, 8, 'Cain said to Abel, his brother, "Let''s go into the field." It happened when they were in the field, that Cain rose up against Abel, his brother, and killed him.'),
  ('cbf5a6aa-5c2e-5442-a46b-fa6160c5c549', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 9, 9, 'Yahweh said to Cain, "Where is Abel, your brother?" He said, "I don''t know. Am I my brother''s keeper?"'),
  ('86824309-5c2f-5fc5-a5a5-a388773649a9', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 10, 10, 'Yahweh said, "What have you done? The voice of your brother''s blood cries to me from the ground.'),
  ('093a4ff9-1088-5928-aa03-28cf52ee095e', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 11, 11, 'Now you are cursed because of the ground, which has opened its mouth to receive your brother''s blood from your hand.'),
  ('2bbb7f74-3823-5792-a128-d7434a6f29e3', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 12, 12, 'From now on, when you till the ground, it won''t yield its strength to you. You shall be a fugitive and a wanderer in the earth."'),
  ('e03952cd-8b0f-5851-a01c-7b1597894f49', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 13, 13, 'Cain said to Yahweh, "My punishment is greater than I can bear.'),
  ('acff4f3e-e7bc-5643-a138-252ae2a31bb7', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 14, 14, 'Behold, you have driven me out this day from the surface of the ground. I will be hidden from your face, and I will be a fugitive and a wanderer in the earth. It will happen that whoever finds me will kill me."'),
  ('0d5f0108-fcb4-5c3c-ac31-547a1cb80165', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 15, 15, 'Yahweh said to him, "Therefore whoever slays Cain, vengeance will be taken on him sevenfold." Yahweh appointed a sign for Cain, lest any finding him should strike him.'),
  ('96b1d4a1-8e9c-5923-a671-2db9e5e530db', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 16, 16, 'Cain went out from Yahweh''s presence, and lived in the land of Nod, east of Eden.'),
  ('4bbffbbd-97f4-58a4-a25f-a5a3ca023950', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 17, 17, 'Cain knew his wife. She conceived, and gave birth to Enoch. He built a city, and called the name of the city, after the name of his son, Enoch.'),
  ('a70139a5-300d-5b78-af9c-a81805ce8c32', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 18, 18, 'To Enoch was born Irad. Irad became the father of Mehujael. Mehujael became the father of Methushael. Methushael became the father of Lamech.'),
  ('972db199-3bec-5563-a232-b3946ea56c73', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 19, 19, 'Lamech took two wives: the name of the one was Adah, and the name of the other Zillah.'),
  ('58badded-d5e3-5dcf-a43e-c5bfdcf2ae8c', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 20, 20, 'Adah gave birth to Jabal, who was the father of those who dwell in tents and have livestock.'),
  ('a985eb7e-dd4a-5822-a8fc-b1203b6b397d', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 21, 21, 'His brother''s name was Jubal, who was the father of all who handle the harp and pipe.'),
  ('962ab80c-ab0c-542c-a3d0-f8ad96bca2b7', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 22, 22, 'Zillah also gave birth to Tubal Cain, the forger of every cutting instrument of brass and iron. Tubal Cain''s sister was Naamah.'),
  ('5886c887-8bf9-5beb-a0d0-9bf2e6639bb3', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 23, 23, 'Lamech said to his wives, "Adah and Zillah, hear my voice. You wives of Lamech, listen to my speech, for I have slain a man for wounding me, a young man for bruising me.'),
  ('a41697a3-5da1-5534-a998-1538a0497824', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 24, 24, 'If Cain will be avenged seven times, truly Lamech seventy-seven times."'),
  ('48019f37-02d6-5114-a732-819146980b59', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 25, 25, 'Adam knew his wife again. She gave birth to a son, and named him Seth, "for God has appointed me another child instead of Abel, for Cain killed him."'),
  ('13d6abbc-3ee8-5c3f-a73f-a7493c4bf15f', '811ca6b3-4622-5aa9-a592-7e01b49714e3', NULL, 26, 26, 'There was also born a son to Seth, and he named him Enosh. Then men began to call on Yahweh''s name.'),
  ('ba452982-bc10-5517-acdc-a9bae4e80e6c', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 1, 1, 'This is the book of the generations of Adam. In the day that God created man, he made him in God''s likeness.'),
  ('690a4990-33ae-56e0-a5c6-5b8f5244a855', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 2, 2, 'He created them male and female, and blessed them, and called their name "Adam," in the day when they were created.'),
  ('72f526fa-4cb5-5a34-aad2-6563965e5604', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 3, 3, 'Adam lived one hundred thirty years, and became the father of a son in his own likeness, after his image, and named him Seth.'),
  ('503fa45e-eaea-5c1a-a1ed-2a0648ebe182', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 4, 4, 'The days of Adam after he became the father of Seth were eight hundred years, and he became the father of sons and daughters.'),
  ('53e05dc1-2707-599e-ad40-fca6d0f660ea', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 5, 5, 'All the days that Adam lived were nine hundred thirty years, then he died.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('22bf74c3-4bd5-5d0c-a81d-6aaf0895205e', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 6, 6, 'Seth lived one hundred five years, and became the father of Enosh.'),
  ('2327c7fe-7931-5e22-a6ec-89768485a3b6', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 7, 7, 'Seth lived after he became the father of Enosh eight hundred seven years, and became the father of sons and daughters.'),
  ('edc1f939-5b50-5b6e-ace4-ea8bff90a1e5', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 8, 8, 'All the days of Seth were nine hundred twelve years, then he died.'),
  ('3eec2c65-bbfc-5ef5-a678-0deed78a278b', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 9, 9, 'Enosh lived ninety years, and became the father of Kenan.'),
  ('0be14b5f-b908-5ab5-ab4b-1952d9153017', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 10, 10, 'Enosh lived after he became the father of Kenan, eight hundred fifteen years, and became the father of sons and daughters.'),
  ('e0fc1ca8-c9fc-5c35-a027-d08b590f952b', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 11, 11, 'All the days of Enosh were nine hundred five years, then he died.'),
  ('e7997f8b-a6d4-55a3-aafe-643257cc922a', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 12, 12, 'Kenan lived seventy years, and became the father of Mahalalel.'),
  ('797632fd-8213-59d8-a7fc-bc928522d1da', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 13, 13, 'Kenan lived after he became the father of Mahalalel eight hundred forty years, and became the father of sons and daughters'),
  ('fde18ca5-65d7-5a6d-a8b3-3f9cb8718ad9', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 14, 14, 'and all the days of Kenan were nine hundred ten years, then he died.'),
  ('22f1ef2e-73d9-5f1b-a1a3-9837fd5b3af0', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 15, 15, 'Mahalalel lived sixty-five years, and became the father of Jared.'),
  ('96a76900-14c3-5b1c-a4b7-0c8494ae066e', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 16, 16, 'Mahalalel lived after he became the father of Jared eight hundred thirty years, and became the father of sons and daughters.'),
  ('7e00f3ba-ffdc-591a-ad40-d1490ee21185', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 17, 17, 'All the days of Mahalalel were eight hundred ninety-five years, then he died.'),
  ('dfd83f7a-6719-5962-aa05-013684675b3e', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 18, 18, 'Jared lived one hundred sixty-two years, and became the father of Enoch.'),
  ('444d814c-59b1-5764-a125-467eca0a95a6', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 19, 19, 'Jared lived after he became the father of Enoch eight hundred years, and became the father of sons and daughters.'),
  ('ba827c6c-1fa9-505a-a813-21446ea14d16', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 20, 20, 'All the days of Jared were nine hundred sixty-two years, then he died.'),
  ('a361bec4-1a6f-59ef-aab3-ded2371e1e14', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 21, 21, 'Enoch lived sixty-five years, and became the father of Methuselah.'),
  ('7d55f997-cccb-5ae6-a388-ec1673a72514', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 22, 22, 'Enoch walked with God after he became the father of Methuselah three hundred years, and became the father of sons and daughters.'),
  ('d5e1e989-5f6b-5828-a7f6-30b23b224f84', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 23, 23, 'All the days of Enoch were three hundred sixty-five years.'),
  ('ae86f722-9c06-5ae8-af40-3f4b11eb852f', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 24, 24, 'Enoch walked with God, and he was not, for God took him.'),
  ('ef0a6b41-ee8a-5de3-ab82-7f9cfd05f218', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 25, 25, 'Methuselah lived one hundred eighty-seven years, and became the father of Lamech.'),
  ('72bb12d5-c44b-58e2-ad0d-89a9b546383d', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 26, 26, 'Methuselah lived after he became the father of Lamech seven hundred eighty-two years, and became the father of sons and daughters.'),
  ('881f7c49-be64-5e17-a3fb-ca52391df335', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 27, 27, 'All the days of Methuselah were nine hundred sixty-nine years, then he died.'),
  ('429976f6-002d-5f6d-a336-83b2f22c10f2', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 28, 28, 'Lamech lived one hundred eighty-two years, and became the father of a son,'),
  ('84420765-118a-59d4-afb2-12b9f76d3ef6', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 29, 29, 'and he named him Noah, saying, "This same will comfort us in our work and in the toil of our hands, because of the ground which Yahweh has cursed."'),
  ('f2b18dc5-92c3-5f6e-a7fc-be4f68a40490', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 30, 30, 'Lamech lived after he became the father of Noah five hundred ninety-five years, and became the father of sons and daughters.'),
  ('40a39f8a-160e-5a30-a99d-56677b494135', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 31, 31, 'All the days of Lamech were seven hundred seventy-seven years, then he died.'),
  ('0c6b1665-f5bc-535a-afd4-8c8ff89fc3f7', '2649f742-a408-5e3c-a721-28b7f67aa6b2', NULL, 32, 32, 'Noah was five hundred years old, and Noah became the father of Shem, Ham, and Japheth.'),
  ('81fdc402-7e88-54bc-a91e-d8422f120311', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 1, 1, 'It happened, when men began to multiply on the surface of the ground, and daughters were born to them,'),
  ('d48f8d47-a2e6-5998-a33d-423ebc84f15f', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 2, 2, 'that God''s sons saw that men''s daughters were beautiful, and they took for themselves wives of all that they chose.'),
  ('c3291929-815b-5a41-a5ed-99ecdbbb5d39', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 3, 3, 'Yahweh said, "My Spirit will not strive with man forever, because he also is flesh; yet will his days be one hundred twenty years."'),
  ('ad4dabf7-d56f-5e05-ab37-22faefa23be8', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 4, 4, 'The Nephilim were in the earth in those days, and also after that, when God''s sons came in to men''s daughters. They bore children to them. Those were the mighty men who were of old, men of renown.'),
  ('9335a13d-29b2-554d-a7b8-b23a5dc36bfd', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 5, 5, 'Yahweh saw that the wickedness of man was great in the earth, and that every imagination of the thoughts of his heart was only evil continually.'),
  ('9f3a44fe-34e5-5862-a3d1-91e90f93d9db', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 6, 6, 'Yahweh was sorry that he had made man on the earth, and it grieved him in his heart.'),
  ('49497159-1216-59cd-a152-0518f3ec88e4', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 7, 7, 'Yahweh said, "I will destroy man whom I have created from the surface of the ground; man, along with animals, creeping things, and birds of the sky; for I am sorry that I have made them."'),
  ('e67e9824-3eab-5309-a04c-49a02b204a2e', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 8, 8, 'But Noah found favor in Yahweh''s eyes.'),
  ('4f9f570e-4bd3-5c0c-aa5b-875a51fced05', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 9, 9, 'This is the history of the generations of Noah. Noah was a righteous man, blameless among the people of his time. Noah walked with God.'),
  ('e1059d18-dfda-5936-a716-f9c0027b36ee', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 10, 10, 'Noah became the father of three sons: Shem, Ham, and Japheth.'),
  ('6133343f-6d32-5627-af1f-3cdfa90d2970', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 11, 11, 'The earth was corrupt before God, and the earth was filled with violence.'),
  ('ec4c354f-362b-5767-a771-8d6a15c21a46', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 12, 12, 'God saw the earth, and saw that it was corrupt, for all flesh had corrupted their way on the earth.'),
  ('759ab01a-135a-5fbf-a8c2-b8e4ec4b7a2a', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 13, 13, 'God said to Noah, "The end of all flesh has come before me, for the earth is filled with violence through them. Behold, I will destroy them with the earth.'),
  ('15d29d8b-0add-5e27-a036-ce0b0247f0ce', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 14, 14, 'Make a ship of gopher wood. You shall make rooms in the ship, and shall seal it inside and outside with pitch.'),
  ('214e4798-9549-5433-a797-517fca847f4c', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 15, 15, 'This is how you shall make it. The length of the ship will be three hundred cubits, its breadth fifty cubits, and its height thirty cubits.'),
  ('e3f23651-e047-59ae-ab6b-ac0e7e183e25', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 16, 16, 'You shall make a roof in the ship, and you shall finish it to a cubit upward. You shall set the door of the ship in its side. You shall make it with lower, second, and third levels.'),
  ('c7d3c0bd-a3d9-501d-a1c1-1415b9bd5c96', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 17, 17, 'I, even I, do bring the flood of waters on this earth, to destroy all flesh having the breath of life from under the sky. Everything that is in the earth will die.'),
  ('2af4b850-2b8f-50ce-a352-606f1f89d01e', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 18, 18, 'But I will establish my covenant with you. You shall come into the ship, you, your sons, your wife, and your sons'' wives with you.'),
  ('cd66fc5c-9b09-5eca-a32b-8d6960f9aec8', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 19, 19, 'Of every living thing of all flesh, you shall bring two of every sort into the ship, to keep them alive with you. They shall be male and female.'),
  ('23201720-6fa8-58ba-a308-aff86b86bacc', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 20, 20, 'Of the birds after their kind, of the livestock after their kind, of every creeping thing of the ground after its kind, two of every sort shall come to you, to keep them alive.'),
  ('83136bb7-9786-510c-a708-bcc1f866f46c', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 21, 21, 'Take with you of all food that is eaten, and gather it to yourself; and it will be for food for you, and for them."'),
  ('ff252fc8-8799-5255-a845-3ae9a3d982fb', '6108b7e1-216d-5e34-aaae-bb4c6bbd821e', NULL, 22, 22, 'Thus Noah did. According to all that God commanded him, so he did.'),
  ('5560c205-b4e3-5b32-ac05-4417a4ebf024', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 1, 1, 'Yahweh said to Noah, "Come with all of your household into the ship, for I have seen your righteousness before me in this generation.'),
  ('5a222220-14bb-54a6-af38-a407868bec25', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 2, 2, 'You shall take seven pairs of every clean animal with you, the male and his female. Of the animals that are not clean, take two, the male and his female.'),
  ('732b5580-cd7c-5183-ac04-488de04396be', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 3, 3, 'Also of the birds of the sky, seven and seven, male and female, to keep seed alive on the surface of all the earth.'),
  ('16e1c73c-5814-5dcc-adcf-e4988313d149', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 4, 4, 'In seven days, I will cause it to rain on the earth for forty days and forty nights. Every living thing that I have made, I will destroy from the surface of the ground."'),
  ('94e8c822-1dfd-51d4-aa01-b432d0eb7792', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 5, 5, 'Noah did everything that Yahweh commanded him.'),
  ('5c1901df-5398-54d7-a9cc-50a6af1defd3', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 6, 6, 'Noah was six hundred years old when the flood of waters came on the earth.'),
  ('5f4bc95a-badd-53b2-a210-293277b5a3c8', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 7, 7, 'Noah went into the ship with his sons, his wife, and his sons'' wives, because of the waters of the flood.'),
  ('7ec3882a-f7bb-52c9-ac14-ddb40f60a39e', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 8, 8, 'Clean animals, animals that are not clean, birds, and everything that creeps on the ground'),
  ('b8a872e9-4ecb-536b-a0fe-7461a83f79e1', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 9, 9, 'went by pairs to Noah into the ship, male and female, as God commanded Noah.'),
  ('d81f6c18-8926-5fe8-a013-4d9155923122', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 10, 10, 'It happened after the seven days, that the waters of the flood came on the earth.'),
  ('e50366d3-2583-5181-a912-ce43a2548d08', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 11, 11, 'In the six hundredth year of Noah''s life, in the second month, on the seventeenth day of the month, on the same day all the fountains of the great deep were burst open, and the sky''s windows were opened.'),
  ('1872643d-5d1d-5482-a14e-7fcd051d03a9', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 12, 12, 'The rain was on the earth forty days and forty nights.'),
  ('19126213-a88b-5114-af5b-a77013e49b8d', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 13, 13, 'In the same day Noah, and Shem, Ham, and Japheth, the sons of Noah, and Noah''s wife, and the three wives of his sons with them, entered into the ship;'),
  ('b9cf612d-fc73-50af-a72f-c208bf949cb0', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 14, 14, 'they, and every animal after its kind, all the livestock after their kind, every creeping thing that creeps on the earth after its kind, and every bird after its kind, every bird of every sort.'),
  ('9e6f4b3e-534d-5e42-a168-526d5aabc8c6', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 15, 15, 'They went to Noah into the ship, by pairs of all flesh with the breath of life in them.'),
  ('bc609cd8-c8d3-56c9-a084-a6d36dd49daf', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 16, 16, 'Those who went in, went in male and female of all flesh, as God commanded him; and Yahweh shut him in.'),
  ('a54f15e8-1d07-5d63-a885-1692b4addde6', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 17, 17, 'The flood was forty days on the earth. The waters increased, and lifted up the ship, and it was lifted up above the earth.'),
  ('00d468b2-51e6-50f5-a248-eb64b543fa01', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 18, 18, 'The waters prevailed, and increased greatly on the earth; and the ship floated on the surface of the waters.'),
  ('41626568-a7ac-529e-ac4d-2bf0f04cb0d2', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 19, 19, 'The waters prevailed exceedingly on the earth. All the high mountains that were under the whole sky were covered.'),
  ('0880818d-248b-5716-a2e8-4c75d91c2310', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 20, 20, 'The waters prevailed fifteen cubits upward, and the mountains were covered.'),
  ('9e2a5805-2b4f-5951-a0c5-5b985aeb7a8f', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 21, 21, 'All flesh died that moved on the earth, including birds, livestock, animals, every creeping thing that creeps on the earth, and every man.'),
  ('73566f09-574f-5103-a1fa-e034e5bff92c', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 22, 22, 'All in whose nostrils was the breath of the spirit of life, of all that was on the dry land, died.'),
  ('9ccd1ef7-bd02-5bdb-ad9d-738e4c86bfa1', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 23, 23, 'Every living thing was destroyed that was on the surface of the ground, including man, livestock, creeping things, and birds of the sky. They were destroyed from the earth. Only Noah was left, and those who were with him in the ship.'),
  ('14cf7c66-c597-5162-af24-47e939e632b4', '6f5b9701-6bef-5727-a283-eec804ad043f', NULL, 24, 24, 'The waters prevailed on the earth one hundred fifty days.'),
  ('effdbab8-0045-52fb-ad44-ef54d2bca88a', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 1, 1, 'God remembered Noah, all the animals, and all the livestock that were with him in the ship; and God made a wind to pass over the earth. The waters subsided.'),
  ('42485611-5828-563d-abcf-9ba0e6e71b9b', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 2, 2, 'The deep''s fountains and the sky''s windows were also stopped, and the rain from the sky was restrained.'),
  ('911b5ecf-dc20-599c-a5e0-1457d27789ef', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 3, 3, 'The waters receded from the earth continually. After the end of one hundred fifty days the waters decreased.'),
  ('17d244fc-f397-5933-a183-7b348798292d', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 4, 4, 'The ship rested in the seventh month, on the seventeenth day of the month, on Ararat''s mountains.'),
  ('a5c2a300-45a9-540d-a775-32adb418b3ab', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 5, 5, 'The waters receded continually until the tenth month. In the tenth month, on the first day of the month, the tops of the mountains were seen.'),
  ('e3d3c86c-4ea3-5aa4-ab80-741553b950e6', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 6, 6, 'It happened at the end of forty days, that Noah opened the window of the ship which he had made,'),
  ('40929470-333a-5254-a990-844382af27a4', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 7, 7, 'and he sent forth a raven. It went back and forth, until the waters were dried up from the earth.'),
  ('f1e3c73d-1d25-508e-ad3b-2b11fd83c27d', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 8, 8, 'He sent forth a dove from him, to see if the waters were abated from the surface of the ground,'),
  ('88316cf8-b767-5d26-a82f-2136db3e67dc', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 9, 9, 'but the dove found no place to rest her foot, and she returned to him into the ship; for the waters were on the surface of the whole earth. He put forth his hand, and took her, and brought her to him into the ship.'),
  ('241b8fbb-5eca-51c0-a764-643490a1e677', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 10, 10, 'He stayed yet another seven days; and again he sent forth the dove out of the ship.'),
  ('26fb7acf-bcad-5306-ac27-73a72f5abb26', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 11, 11, 'The dove came back to him at evening, and, behold, in her mouth was an olive leaf plucked off. So Noah knew that the waters were abated from the earth.'),
  ('c4090bec-ac75-5587-af05-e392fd88a981', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 12, 12, 'He stayed yet another seven days, and sent forth the dove; and she didn''t return to him any more.'),
  ('551ee0f7-ef74-5884-a062-ca9d68170cf3', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 13, 13, 'It happened in the six hundred first year, in the first month, the first day of the month, the waters were dried up from the earth. Noah removed the covering of the ship, and looked. He saw that the surface of the ground was dried.'),
  ('c9b2b3fd-a09a-5976-a60c-3a1f893ffb1a', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 14, 14, 'In the second month, on the twenty-seventh day of the month, the earth was dry.'),
  ('a4e8caa7-9bc4-5b51-ad9f-23647779b497', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 15, 15, 'God spoke to Noah, saying,'),
  ('0fbdc1ed-fcdb-58c6-a950-699c3db1e463', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 16, 16, '"Go out of the ship, you, and your wife, and your sons, and your sons'' wives with you.'),
  ('54eb3e15-61e2-5a63-afc1-19aeeae63731', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 17, 17, 'Bring forth with you every living thing that is with you of all flesh, including birds, livestock, and every creeping thing that creeps on the earth, that they may breed abundantly in the earth, and be fruitful, and multiply on the earth."'),
  ('9d1cbc91-1c3a-54cc-a46c-a22905c54894', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 18, 18, 'Noah went forth, with his sons, his wife, and his sons'' wives with him.'),
  ('57e3326f-d246-5887-a1d0-3ff7ff60e7af', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 19, 19, 'Every animal, every creeping thing, and every bird, whatever moves on the earth, after their families, went out of the ship.'),
  ('2cc61b89-b79b-538b-aaa4-02317e514ef6', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 20, 20, 'Noah built an altar to Yahweh, and took of every clean animal, and of every clean bird, and offered burnt offerings on the altar.'),
  ('88ae924e-0abb-53b1-a3c4-d49e83373f23', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 21, 21, 'Yahweh smelled the pleasant aroma. Yahweh said in his heart, "I will not again curse the ground any more for man''s sake, because the imagination of man''s heart is evil from his youth; neither will I ever again strike everything living, as I have done.'),
  ('c3297a53-f0eb-59fd-aed0-e7d479a5774f', '045dffb9-6818-5b25-a806-10b382062c5b', NULL, 22, 22, 'While the earth remains, seed time and harvest, and cold and heat, and summer and winter, and day and night shall not cease."'),
  ('89921e54-7759-56e9-ad4a-a8a27947c6d2', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 1, 1, 'God blessed Noah and his sons, and said to them, "Be fruitful, and multiply, and replenish the earth.'),
  ('a504e80d-18ad-5266-a294-1c2c06608c75', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 2, 2, 'The fear of you and the dread of you will be on every animal of the earth, and on every bird of the sky. Everything that the ground teems with, and all the fish of the sea are delivered into your hand.'),
  ('f7c0c8b0-8bd8-5604-af2e-8dd174dbe539', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 3, 3, 'Every moving thing that lives will be food for you. As the green herb, I have given everything to you.'),
  ('e062dd6a-20c9-5144-a126-76ec7dff7407', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 4, 4, 'But flesh with its life, its blood, you shall not eat.'),
  ('3d7601fa-4f15-54ae-ae46-1e40183f7f52', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 5, 5, 'I will surely require your blood of your lives. At the hand of every animal I will require it. At the hand of man, even at the hand of every man''s brother, I will require the life of man.'),
  ('46f6e9a0-e4f0-561f-a5fb-882fb5d476cb', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 6, 6, 'Whoever sheds man''s blood, his blood will be shed by man, for God made man in his own image.'),
  ('cf62111f-4036-529d-a2f6-4afc1cfd0e39', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 7, 7, 'Be fruitful and multiply. Bring forth abundantly in the earth, and multiply in it."'),
  ('5b1fab11-ff92-57a1-a398-3dc5fd1db2ff', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 8, 8, 'God spoke to Noah and to his sons with him, saying,'),
  ('27b1bf82-ba17-5c66-a134-b7aec8553b71', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 9, 9, '"As for me, behold, I establish my covenant with you, and with your offspring after you,'),
  ('1f0ba730-5ad1-5da2-a6bc-b10fa9fff7cb', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 10, 10, 'and with every living creature that is with you: the birds, the livestock, and every animal of the earth with you, of all that go out of the ship, even every animal of the earth.'),
  ('ef3e588f-b1bb-530f-adc8-b25f16b36d0e', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 11, 11, 'I will establish my covenant with you: all flesh will not be cut off any more by the waters of the flood, neither will there ever again be a flood to destroy the earth."'),
  ('29b0999c-a75c-57f0-a059-64e9487e7ce4', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 12, 12, 'God said, "This is the token of the covenant which I make between me and you and every living creature that is with you, for perpetual generations:'),
  ('730b6c09-8d29-5f9a-a8a8-8c9fb412e3ea', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 13, 13, 'I set my rainbow in the cloud, and it will be for a sign of a covenant between me and the earth.'),
  ('59a0c9be-f64e-5f61-a103-99800905723d', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 14, 14, 'It will happen, when I bring a cloud over the earth, that the rainbow will be seen in the cloud,'),
  ('43c5de00-b602-56e4-ae3f-989b94fbbdd0', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 15, 15, 'and I will remember my covenant, which is between me and you and every living creature of all flesh, and the waters will no more become a flood to destroy all flesh.'),
  ('6a8e0b44-e04c-5375-a8a4-411e81256cfa', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 16, 16, 'The rainbow will be in the cloud. I will look at it, that I may remember the everlasting covenant between God and every living creature of all flesh that is on the earth."'),
  ('bedb1c2f-c3e5-59a5-a77b-ca24fa8277d0', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 17, 17, 'God said to Noah, "This is the token of the covenant which I have established between me and all flesh that is on the earth."'),
  ('c09230a5-d060-53b8-a6f9-68d7acc7b102', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 18, 18, 'The sons of Noah who went forth from the ship were Shem, Ham, and Japheth. Ham is the father of Canaan.'),
  ('31d5c2c1-e590-5bf8-aaf8-fa93f4053e3e', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 19, 19, 'These three were the sons of Noah, and from these, the whole earth was populated.'),
  ('ad6f41f3-6ca2-5903-a5e3-e1591982f8fb', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 20, 20, 'Noah began to be a farmer, and planted a vineyard.'),
  ('66b854d2-c8a6-5585-a4f5-52c31d2bcf9a', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 21, 21, 'He drank of the wine and got drunk. He was uncovered within his tent.'),
  ('cd2f546a-f364-56a2-a69c-63b7206ca806', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 22, 22, 'Ham, the father of Canaan, saw the nakedness of his father, and told his two brothers outside.'),
  ('d7acd1e3-314b-5394-a3f6-ee331a64f933', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 23, 23, 'Shem and Japheth took a garment, and laid it on both their shoulders, went in backwards, and covered the nakedness of their father. Their faces were backwards, and they didn''t see their father''s nakedness.'),
  ('496f896c-f896-5d83-ab94-76ca3f3eda17', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 24, 24, 'Noah awoke from his wine, and knew what his youngest son had done to him.'),
  ('197f0881-220a-5dcf-a25f-76b87301c7a2', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 25, 25, 'He said, "Canaan is cursed. He will be servant of servants to his brothers."'),
  ('a0cedb78-4b92-5e5b-a2b8-7639148a51b3', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 26, 26, 'He said, "Blessed be Yahweh, the God of Shem. Let Canaan be his servant.'),
  ('8bd47382-ae1d-5068-a712-e3c6f5f82d4e', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 27, 27, 'May God enlarge Japheth. Let him dwell in the tents of Shem. Let Canaan be his servant."'),
  ('2d3d8c14-0a1c-5184-a5d1-b6bc65595aee', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 28, 28, 'Noah lived three hundred fifty years after the flood.'),
  ('95d8bca7-b0c8-5bd2-aaa1-f4a0554dc975', 'aedc8400-6cd6-57dd-a0f4-715b6d8755a1', NULL, 29, 29, 'All the days of Noah were nine hundred fifty years, then he died.'),
  ('f31616ca-a993-525f-a35d-7ecd69be71f4', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 1, 1, 'Now this is the history of the generations of the sons of Noah and of Shem, Ham, and Japheth. Sons were born to them after the flood.'),
  ('193d39de-8c74-583b-a029-c2d9b03f8e34', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 2, 2, 'The sons of Japheth: Gomer, Magog, Madai, Javan, Tubal, Meshech, and Tiras.'),
  ('87f39163-248a-5e81-a645-e96ad22df3a2', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 3, 3, 'The sons of Gomer: Ashkenaz, Riphath, and Togarmah.'),
  ('a08beae9-c031-54da-a005-5f61dd200147', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 4, 4, 'The sons of Javan: Elishah, Tarshish, Kittim, and Dodanim.'),
  ('e611f639-8e5d-5491-a6f5-ca2383b11554', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 5, 5, 'Of these were the islands of the nations divided in their lands, everyone after his language, after their families, in their nations.'),
  ('b5610997-a7e6-57f5-a763-832c3687cf9f', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 6, 6, 'The sons of Ham: Cush, Mizraim, Put, and Canaan.'),
  ('abae9d95-bced-52b5-a430-6896b66b9ef5', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 7, 7, 'The sons of Cush: Seba, Havilah, Sabtah, Raamah, and Sabteca. The sons of Raamah: Sheba and Dedan.'),
  ('750188c9-3df0-5f35-aea6-a7f28f7dab1b', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 8, 8, 'Cush became the father of Nimrod. He began to be a mighty one in the earth.'),
  ('972a16d2-dc99-54f5-a755-b8b11cdceff0', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 9, 9, 'He was a mighty hunter before Yahweh. Therefore it is said, "Like Nimrod, a mighty hunter before Yahweh."'),
  ('704ee5ec-dec3-5976-a6fe-77f0b24e844a', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 10, 10, 'The beginning of his kingdom was Babel, Erech, Accad, and Calneh, in the land of Shinar.'),
  ('9e7afc95-63b6-569c-a693-aeac3e684bbf', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 11, 11, 'Out of that land he went forth into Assyria, and built Nineveh, Rehoboth Ir, Calah,'),
  ('46bee01a-8818-5aac-aaf2-a12a48d3f81c', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 12, 12, 'and Resen between Nineveh and Calah (the same is the great city).'),
  ('591d6e37-672f-5267-a59c-9a781ffb2736', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 13, 13, 'Mizraim became the father of Ludim, Anamim, Lehabim, Naphtuhim,'),
  ('a122cdee-4204-510d-ae72-51619c26522e', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 14, 14, 'Pathrusim, Casluhim (which the Philistines descended from), and Caphtorim.'),
  ('0199d342-e4b5-5c18-a7df-ac4a3fd55bb9', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 15, 15, 'Canaan became the father of Sidon (his firstborn), Heth,'),
  ('d854ab21-7d7f-5cf5-a7fe-5b9ed5650afc', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 16, 16, 'the Jebusite, the Amorite, the Girgashite,'),
  ('d3cfca9f-91ee-5c2f-aea3-6bf1d2fe707e', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 17, 17, 'the Hivite, the Arkite, the Sinite,'),
  ('93fc44e0-ce50-51b4-a837-72da78f919c6', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 18, 18, 'the Arvadite, the Zemarite, and the Hamathite. Afterward the families of the Canaanites were spread abroad.'),
  ('8c49219a-a0c5-50cd-a9ec-fe554aeb74ac', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 19, 19, 'The border of the Canaanites was from Sidon, as you go toward Gerar, to Gaza; as you go toward Sodom, Gomorrah, Admah, and Zeboiim, to Lasha.'),
  ('e8e2c4c4-5da0-5ce3-af69-5650a51f3efb', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 20, 20, 'These are the sons of Ham, after their families, after their languages, in their lands, in their nations.'),
  ('ddc56545-0f48-5cc5-a7d7-f1fec797c388', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 21, 21, 'To Shem, the father of all the children of Eber, the elder brother of Japheth, to him also were children born.'),
  ('25023a9d-ce33-51e8-aea1-49e387fd90f6', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 22, 22, 'The sons of Shem: Elam, Asshur, Arpachshad, Lud, and Aram.'),
  ('a0d9fc94-d105-5204-ad7a-69b936c10c93', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 23, 23, 'The sons of Aram: Uz, Hul, Gether, and Mash.'),
  ('655734b1-0c8d-56b9-a25a-29f382a6134d', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 24, 24, 'Arpachshad became the father of Shelah. Shelah became the father of Eber.'),
  ('0c494da4-9ca9-5ce7-acba-b345fa75337a', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 25, 25, 'To Eber were born two sons. The name of the one was Peleg, for in his days the earth was divided. His brother''s name was Joktan.'),
  ('b46f9a8c-f300-57b2-a664-070edd55454c', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 26, 26, 'Joktan became the father of Almodad, Sheleph, Hazarmaveth, Jerah,'),
  ('be1e3b66-9af7-5315-aeea-f4f8b9ce8d98', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 27, 27, 'Hadoram, Uzal, Diklah,'),
  ('8e53f20f-8bff-55ce-ae2d-024c997aec7e', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 28, 28, 'Obal, Abimael, Sheba,'),
  ('3027c353-6835-5107-a2fe-93a7379aa38a', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 29, 29, 'Ophir, Havilah, and Jobab. All these were the sons of Joktan.'),
  ('2969f5bb-3856-5bab-a937-f4695716e79e', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 30, 30, 'Their dwelling was from Mesha, as you go toward Sephar, the mountain of the east.'),
  ('f8a047c7-a304-5894-afad-ea4ff2e51ddf', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 31, 31, 'These are the sons of Shem, after their families, after their languages, in their lands, after their nations.'),
  ('133e05e7-397f-541f-a807-f6b335990bf9', '33992be1-a76d-501d-a0dc-7e583d32cebc', NULL, 32, 32, 'These are the families of the sons of Noah, after their generations, in their nations. Of these were the nations divided in the earth after the flood.'),
  ('a70c4803-71aa-5226-afe9-ce15a86fbc6a', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 1, 1, 'The whole earth was of one language and of one speech.'),
  ('75c7d68c-859d-53e8-a835-a03de0b5bcee', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 2, 2, 'It happened, as they traveled east, that they found a plain in the land of Shinar, and they lived there.'),
  ('8dd9078e-2882-586c-a17f-f81670791141', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 3, 3, 'They said one to another, "Come, let''s make bricks, and burn them thoroughly." They had brick for stone, and they used tar for mortar.'),
  ('03fe5ea6-8aaf-5fd1-ae63-5048c8461842', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 4, 4, 'They said, "Come, let''s build ourselves a city, and a tower whose top reaches to the sky, and let''s make ourselves a name, lest we be scattered abroad on the surface of the whole earth."'),
  ('a9424a6e-bdea-5ef5-a66a-495400c14882', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 5, 5, 'Yahweh came down to see the city and the tower, which the children of men built.'),
  ('f1a84530-cae4-5571-af74-cef609827792', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 6, 6, 'Yahweh said, "Behold, they are one people, and they have all one language, and this is what they begin to do. Now nothing will be withheld from them, which they intend to do.'),
  ('62dfa66e-6a1f-5a4d-a35b-29f14d26e719', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 7, 7, 'Come, let''s go down, and there confuse their language, that they may not understand one another''s speech."'),
  ('91f2d8ff-d8a1-50af-a73a-51a15eb2dc6f', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 8, 8, 'So Yahweh scattered them abroad from there on the surface of all the earth. They stopped building the city.'),
  ('2d151e61-49e5-5673-a623-b40cd2294025', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 9, 9, 'Therefore its name was called Babel, because there Yahweh confused the language of all the earth. From there, Yahweh scattered them abroad on the surface of all the earth.'),
  ('81cc49ac-cdbf-581a-acbc-2077b6b4dbc0', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 10, 10, 'This is the history of the generations of Shem. Shem was one hundred years old and became the father of Arpachshad two years after the flood.'),
  ('04fd6ebc-3527-5cfd-a027-43623050f9e0', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 11, 11, 'Shem lived five hundred years after he became the father of Arpachshad, and became the father of sons and daughters.'),
  ('a17dfa35-b13c-571a-a08f-0a2f24374c18', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 12, 12, 'Arpachshad lived thirty-five years and became the father of Shelah.'),
  ('36782d8a-f3e5-5cfe-a07c-4c1ebaaf0a4e', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 13, 13, 'Arpachshad lived four hundred three years after he became the father of Shelah, and became the father of sons and daughters.'),
  ('15704797-e8f9-5d70-a99a-caedb2df8952', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 14, 14, 'Shelah lived thirty years, and became the father of Eber:'),
  ('898b7d9d-7f5f-5fce-a335-f2cf1fa2d539', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 15, 15, 'and Shelah lived four hundred three years after he became the father of Eber, and became the father of sons and daughters.'),
  ('ecb6a0cd-9b09-540e-a2b9-77f7d90b8356', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 16, 16, 'Eber lived thirty-four years, and became the father of Peleg.'),
  ('5c7d2438-4be0-57b0-aafe-e5272132b7a0', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 17, 17, 'Eber lived four hundred thirty years after he became the father of Peleg, and became the father of sons and daughters.'),
  ('5982cfad-d51d-5e8b-affb-40b37b889e28', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 18, 18, 'Peleg lived thirty years, and became the father of Reu.'),
  ('fcb1bd39-b1de-5c29-a94b-5276aef208ca', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 19, 19, 'Peleg lived two hundred nine years after he became the father of Reu, and became the father of sons and daughters.'),
  ('c0132e5a-a45a-565b-a9a2-612ab22a0912', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 20, 20, 'Reu lived thirty-two years, and became the father of Serug.'),
  ('810c5e6d-2b1c-5d85-aaca-a9b8f1733d65', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 21, 21, 'Reu lived two hundred seven years after he became the father of Serug, and became the father of sons and daughters.'),
  ('2a809a55-b40d-5f25-a0bf-1f9c04e7ad93', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 22, 22, 'Serug lived thirty years, and became the father of Nahor.'),
  ('1c27455f-efeb-55f7-a2dd-3187637c3de6', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 23, 23, 'Serug lived two hundred years after he became the father of Nahor, and became the father of sons and daughters.'),
  ('3dbffb1c-b69d-5ac4-aeda-91482c4f76ff', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 24, 24, 'Nahor lived twenty-nine years, and became the father of Terah.'),
  ('f6c8244c-1ed6-5bbd-a28a-8a57c6da264e', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 25, 25, 'Nahor lived one hundred nineteen years after he became the father of Terah, and became the father of sons and daughters.'),
  ('5762883b-623f-5af0-a303-e14775777673', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 26, 26, 'Terah lived seventy years, and became the father of Abram, Nahor, and Haran.'),
  ('4a1d076a-9c59-5ad9-af57-00b6525536e1', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 27, 27, 'Now this is the history of the generations of Terah. Terah became the father of Abram, Nahor, and Haran. Haran became the father of Lot.'),
  ('5b394930-e544-577c-a5cd-a0bf77a5ae80', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 28, 28, 'Haran died before his father Terah in the land of his birth, in Ur of the Chaldees.'),
  ('8e2d2c0c-2b82-57fe-a9cd-74f6b60ab461', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 29, 29, 'Abram and Nahor took wives. The name of Abram''s wife was Sarai, and the name of Nahor''s wife, Milcah, the daughter of Haran who was also the father of Iscah.'),
  ('71d73523-d779-52b0-a2cb-6ba95194312e', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 30, 30, 'Sarai was barren. She had no child.'),
  ('f9f6b86c-97d0-5d00-a4d2-f6cbe2bfb8fa', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 31, 31, 'Terah took Abram his son, Lot the son of Haran, his son''s son, and Sarai his daughter-in-law, his son Abram''s wife. They went forth from Ur of the Chaldees, to go into the land of Canaan. They came to Haran and lived there.'),
  ('19ca8a65-7169-5ea1-ae42-3736c06dba00', '6e03e637-c6bd-5e88-af00-b993680a9498', NULL, 32, 32, 'The days of Terah were two hundred five years. Terah died in Haran.'),
  ('1f06befe-ded6-5621-a13a-37b81037166e', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 1, 1, 'Now Yahweh said to Abram, "Get out of your country, and from your relatives, and from your father''s house, to the land that I will show you.'),
  ('e09f8728-2baf-5fe8-a8e2-65616e561c9f', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 2, 2, 'I will make of you a great nation. I will bless you and make your name great. You will be a blessing.'),
  ('dd71a836-d309-5e60-abf0-1eb75f78ac29', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 3, 3, 'I will bless those who bless you, and I will curse him who curses you. All of the families of the earth will be blessed in you."'),
  ('5743ad5a-9abd-5b61-a773-e6a3d5e67998', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 4, 4, 'So Abram went, as Yahweh had spoken to him. Lot went with him. Abram was seventy-five years old when he departed out of Haran.'),
  ('a0393bda-7faf-58fd-aa20-54a7c930760c', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 5, 5, 'Abram took Sarai his wife, Lot his brother''s son, all their substance that they had gathered, and the souls whom they had gotten in Haran, and they went forth to go into the land of Canaan. Into the land of Canaan they came.'),
  ('89778810-7569-50e7-a312-5e9e7346fdb7', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 6, 6, 'Abram passed through the land to the place of Shechem, to the oak of Moreh. The Canaanite was then in the land.'),
  ('265d7a1a-5afd-5481-ada6-498d22a6c990', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 7, 7, 'Yahweh appeared to Abram and said, "I will give this land to your seed." He built an altar there to Yahweh, who appeared to him.'),
  ('4f4b7122-f61a-5211-aca7-1128ba69a308', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 8, 8, 'He left from there to the mountain on the east of Bethel, and pitched his tent, having Bethel on the west, and Ai on the east. There he built an altar to Yahweh and called on the name of Yahweh.'),
  ('e702ef59-bae7-535e-a27d-31b4206ae657', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 9, 9, 'Abram traveled, going on still toward the South.'),
  ('6ca07556-9cf6-5f41-a043-ae97c24a176d', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 10, 10, 'There was a famine in the land. Abram went down into Egypt to live as a foreigner there, for the famine was severe in the land.'),
  ('e5299463-61c0-52de-a3fc-46446e13d70a', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 11, 11, 'It happened, when he had come near to enter Egypt, that he said to Sarai his wife, "See now, I know that you are a beautiful woman to look at.'),
  ('3811fa02-de5c-5ef5-a707-0143386529ac', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 12, 12, 'It will happen, when the Egyptians will see you, that they will say, ''This is his wife.'' They will kill me, but they will save you alive.'),
  ('8284c162-3693-558b-a816-379ec9e1f071', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 13, 13, 'Please say that you are my sister, that it may be well with me for your sake, and that my soul may live because of you."'),
  ('f9e5d500-3175-59ba-a768-4e052e5824ac', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 14, 14, 'It happened that when Abram had come into Egypt, the Egyptians saw that the woman was very beautiful.'),
  ('b7d445c4-55be-5185-a011-96bfa4297324', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 15, 15, 'The princes of Pharaoh saw her, and praised her to Pharaoh; and the woman was taken into Pharaoh''s house.'),
  ('718516f9-5c4d-5172-a723-c949fbfb2028', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 16, 16, 'He dealt well with Abram for her sake. He had sheep, cattle, male donkeys, male servants, female servants, female donkeys, and camels.'),
  ('bb849298-198a-584a-ab61-f5209651e6a5', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 17, 17, 'Yahweh plagued Pharaoh and his house with great plagues because of Sarai, Abram''s wife.'),
  ('61de1df3-ff56-5fea-a1d1-3216f565f41c', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 18, 18, 'Pharaoh called Abram and said, "What is this that you have done to me? Why didn''t you tell me that she was your wife?'),
  ('bfbafdcc-2432-5e89-aca6-402ce59d950c', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 19, 19, 'Why did you say, ''She is my sister,'' so that I took her to be my wife? Now therefore, see your wife, take her, and go your way."'),
  ('09012b30-dae5-5b38-a851-5037f01e0f8c', '26713eca-9da4-54b3-a88b-b235c08cdc43', NULL, 20, 20, 'Pharaoh commanded men concerning him, and they brought him on the way with his wife and all that he had.'),
  ('8ba29512-af7e-598f-a691-2143d6cdcffa', '20231a11-3a50-5b35-af4c-684117278190', NULL, 1, 1, 'Abram went up out of Egypt: he, his wife, all that he had, and Lot with him, into the South.'),
  ('de40a6cf-fa49-550d-a530-379d10cbf30e', '20231a11-3a50-5b35-af4c-684117278190', NULL, 2, 2, 'Abram was very rich in livestock, in silver, and in gold.'),
  ('e17676a4-29af-5fa0-a758-321d80d54bc9', '20231a11-3a50-5b35-af4c-684117278190', NULL, 3, 3, 'He went on his journeys from the South even to Bethel, to the place where his tent had been at the beginning, between Bethel and Ai,'),
  ('caa06bb0-58b7-5e20-ad18-0484c65bc62c', '20231a11-3a50-5b35-af4c-684117278190', NULL, 4, 4, 'to the place of the altar, which he had made there at the first. There Abram called on the name of Yahweh.'),
  ('c545148b-5600-5a74-afae-3bd277d2c331', '20231a11-3a50-5b35-af4c-684117278190', NULL, 5, 5, 'Lot also, who went with Abram, had flocks, and herds, and tents.'),
  ('f756245b-1db7-5a82-af63-1a88bd89f429', '20231a11-3a50-5b35-af4c-684117278190', NULL, 6, 6, 'The land was not able to bear them, that they might live together: for their substance was great, so that they could not live together.'),
  ('021c7b81-7466-592a-ae45-456bf646d45e', '20231a11-3a50-5b35-af4c-684117278190', NULL, 7, 7, 'There was a strife between the herdsmen of Abram''s livestock and the herdsmen of Lot''s livestock: and the Canaanite and the Perizzite lived in the land at that time.'),
  ('7ced9997-0780-5bd4-a56b-5ad671190a12', '20231a11-3a50-5b35-af4c-684117278190', NULL, 8, 8, 'Abram said to Lot, "Please, let there be no strife between me and you, and between my herdsmen and your herdsmen; for we are relatives.'),
  ('3939dc5b-a88f-5223-ae26-cbf2ac9b15de', '20231a11-3a50-5b35-af4c-684117278190', NULL, 9, 9, 'Isn''t the whole land before you? Please separate yourself from me. If you go to the left hand, then I will go to the right. Or if you go to the right hand, then I will go to the left."'),
  ('1a0d4c90-a7f6-5f7d-a157-b228efd30bb1', '20231a11-3a50-5b35-af4c-684117278190', NULL, 10, 10, 'Lot lifted up his eyes, and saw all the plain of the Jordan, that it was well-watered everywhere, before Yahweh destroyed Sodom and Gomorrah, like the garden of Yahweh, like the land of Egypt, as you go to Zoar.'),
  ('8ff3b569-8678-5ad9-aa17-e8153e9fd6c1', '20231a11-3a50-5b35-af4c-684117278190', NULL, 11, 11, 'So Lot chose the Plain of the Jordan for himself. Lot traveled east, and they separated themselves the one from the other.'),
  ('255c45a6-89a4-5cbb-a794-fd776dff797c', '20231a11-3a50-5b35-af4c-684117278190', NULL, 12, 12, 'Abram lived in the land of Canaan, and Lot lived in the cities of the plain, and moved his tent as far as Sodom.'),
  ('01250fe3-c2c4-577d-a4dc-017883809235', '20231a11-3a50-5b35-af4c-684117278190', NULL, 13, 13, 'Now the men of Sodom were exceedingly wicked and sinners against Yahweh.'),
  ('6a37f62a-dbdc-5166-a99d-dc5d0e12c44a', '20231a11-3a50-5b35-af4c-684117278190', NULL, 14, 14, 'Yahweh said to Abram, after Lot was separated from him, "Now, lift up your eyes, and look from the place where you are, northward and southward and eastward and westward,'),
  ('439f50f9-51f8-5dd3-a7d7-fa1efcf345b1', '20231a11-3a50-5b35-af4c-684117278190', NULL, 15, 15, 'for all the land which you see, I will give to you, and to your offspring forever.'),
  ('b4a8e70c-7ab9-5afb-a2e2-9046b11c6087', '20231a11-3a50-5b35-af4c-684117278190', NULL, 16, 16, 'I will make your offspring as the dust of the earth, so that if a man can number the dust of the earth, then your seed may also be numbered.'),
  ('50a655c4-d884-5085-aec3-2367b2169b26', '20231a11-3a50-5b35-af4c-684117278190', NULL, 17, 17, 'Arise, walk through the land in its length and in its breadth; for I will give it to you."'),
  ('e7283e80-23f0-5915-adb7-9550710dad6e', '20231a11-3a50-5b35-af4c-684117278190', NULL, 18, 18, 'Abram moved his tent, and came and lived by the oaks of Mamre, which are in Hebron, and built an altar there to Yahweh.'),
  ('61dda065-a007-5d1e-a84c-25d78dc476bf', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 1, 1, 'It happened in the days of Amraphel, king of Shinar, Arioch, king of Ellasar, Chedorlaomer, king of Elam, and Tidal, king of Goiim,'),
  ('3ed41ea6-31d0-5b7f-aa3d-d962fc0a82ae', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 2, 2, 'that they made war with Bera, king of Sodom, and with Birsha, king of Gomorrah, Shinab, king of Admah, and Shemeber, king of Zeboiim, and the king of Bela (the same is Zoar).'),
  ('7e5a5df8-ba78-5959-a93c-9fc1a1b80abb', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 3, 3, 'All these joined together in the valley of Siddim (the same is the Salt Sea).'),
  ('9a7030f4-3de6-5c5c-a3fe-6e7591fa932b', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 4, 4, 'Twelve years they served Chedorlaomer, and in the thirteenth year, they rebelled.'),
  ('d0b358f1-f4d2-5350-ad7e-ec247380e839', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 5, 5, 'In the fourteenth year Chedorlaomer came, and the kings who were with him, and struck the Rephaim in Ashteroth Karnaim, and the Zuzim in Ham, and the Emim in Shaveh Kiriathaim,'),
  ('f4fbf25a-8b59-570e-a143-52ef792b7bfb', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 6, 6, 'and the Horites in their Mount Seir, to Elparan, which is by the wilderness.'),
  ('ceb3cdef-d52d-5e85-a765-e36bb7f3b260', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 7, 7, 'They returned, and came to En Mishpat (the same is Kadesh), and struck all the country of the Amalekites, and also the Amorites, that lived in Hazazon Tamar.'),
  ('31a5eec7-49ec-5ee4-a6ae-c182984bb843', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 8, 8, 'The king of Sodom, and the king of Gomorrah, and the king of Admah, and the king of Zeboiim, and the king of Bela (the same is Zoar) went out; and they set the battle in array against them in the valley of Siddim;'),
  ('799ede98-51d8-5cec-a051-0432686f913c', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 9, 9, 'against Chedorlaomer king of Elam, and Tidal king of Goiim, and Amraphel king of Shinar, and Arioch king of Ellasar; four kings against the five.'),
  ('b47c78f5-e7b4-5984-a5d1-9f53b9bac253', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 10, 10, 'Now the valley of Siddim was full of tar pits; and the kings of Sodom and Gomorrah fled, and they fell there, and those who remained fled to the hills.'),
  ('50f69392-31f1-5bf2-ab10-4f3d77a841d0', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 11, 11, 'They took all the goods of Sodom and Gomorrah, and all their food, and went their way.'),
  ('be18bccd-adae-5b10-a0ed-0aef8b7e7f9e', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 12, 12, 'They took Lot, Abram''s brother''s son, who lived in Sodom, and his goods, and departed.'),
  ('c616e439-d32f-5feb-a1dc-4749a9428ad6', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 13, 13, 'One who had escaped came and told Abram, the Hebrew. Now he lived by the oaks of Mamre, the Amorite, brother of Eshcol, and brother of Aner; and these were allies of Abram.'),
  ('42743f65-82e9-575c-a168-9395124b485f', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 14, 14, 'When Abram heard that his relative was taken captive, he led forth his trained men, born in his house, three hundred and eighteen, and pursued as far as Dan.'),
  ('dbfc8bb7-318d-5c9b-abef-a019cc97cc3d', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 15, 15, 'He divided himself against them by night, he and his servants, and struck them, and pursued them to Hobah, which is on the left hand of Damascus.'),
  ('b9b5deff-e687-5e74-a369-516199bc3e8a', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 16, 16, 'He brought back all the goods, and also brought back his relative, Lot, and his goods, and the women also, and the people.'),
  ('a2eeeabb-9dde-5153-acdf-91898e584bdb', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 17, 17, 'The king of Sodom went out to meet him, after his return from the slaughter of Chedorlaomer and the kings who were with him, at the valley of Shaveh (that is, the King''s Valley).'),
  ('11707c11-8da9-5ce2-a57d-70523492e72f', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 18, 18, 'Melchizedek king of Salem brought out bread and wine: and he was priest of God Most High.'),
  ('5a10a4f6-f9b4-5441-a71f-70cb62d8264f', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 19, 19, 'He blessed him, and said, "Blessed be Abram of God Most High, possessor of heaven and earth:'),
  ('9e3a7e4f-0dc0-579f-a0f4-7351986a340e', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 20, 20, 'and blessed be God Most High, who has delivered your enemies into your hand." Abram gave him a tenth of all.'),
  ('e85f49ff-cd64-51ae-ab48-3e0b55343361', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 21, 21, 'The king of Sodom said to Abram, "Give me the people, and take the goods to yourself."'),
  ('d41c43df-8003-54de-a0b3-9bce3b3013e4', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 22, 22, 'Abram said to the king of Sodom, "I have lifted up my hand to Yahweh, God Most High, possessor of heaven and earth,'),
  ('11099e5a-8252-5e23-a21b-1a458d864b1b', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 23, 23, 'that I will not take a thread nor a sandal strap nor anything that is yours, lest you should say, ''I have made Abram rich.'''),
  ('c5e7bc8b-3dcb-55ea-a940-6dd45eef8fa9', '300ca940-5f12-55bf-a99c-166d72a4a68d', NULL, 24, 24, 'I will accept nothing from you except that which the young men have eaten, and the portion of the men who went with me: Aner, Eshcol, and Mamre. Let them take their portion."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('d087c1d8-7e4c-5745-a133-618bc753b217', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 1, 1, 'After these things the word of Yahweh came to Abram in a vision, saying, "Don''t be afraid, Abram. I am your shield, your exceedingly great reward."'),
  ('ffe8cc86-e3b9-51cb-a950-943181363909', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 2, 2, 'Abram said, "Lord Yahweh, what will you give me, since I go childless, and he who will inherit my estate is Eliezer of Damascus?"'),
  ('40c9c360-0cbe-5ad2-abda-19347533ba3f', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 3, 3, 'Abram said, "Behold, to me you have given no seed: and, behold, one born in my house is my heir."'),
  ('79a10110-9a04-5f43-aa84-f29ce5479344', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 4, 4, 'Behold, the word of Yahweh came to him, saying, "This man will not be your heir, but he who will come forth out of your own body will be your heir."'),
  ('8e0c0bfc-a132-5abf-a7f0-fdc4b647a608', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 5, 5, 'Yahweh brought him outside, and said, "Look now toward the sky, and count the stars, if you are able to count them." He said to Abram, "So shall your seed be."'),
  ('70102312-e642-5be3-a04d-7ca2ac74d607', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 6, 6, 'He believed in Yahweh; and he reckoned it to him for righteousness.'),
  ('598fba9b-22a6-5ec6-a441-103d317b74d3', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 7, 7, 'He said to him, "I am Yahweh who brought you out of Ur of the Chaldees, to give you this land to inherit it."'),
  ('1dd6c9ad-704e-5683-a764-3179eaf9b8c5', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 8, 8, 'He said, "Lord Yahweh, how will I know that I will inherit it?"'),
  ('21bec9ff-7a79-51c0-a5c4-52a2ae1a8582', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 9, 9, 'He said to him, "Bring me a heifer three years old, a female goat three years old, a ram three years old, a turtledove, and a young pigeon."'),
  ('ce78aeda-bafb-5f90-ab4e-f105d648fadb', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 10, 10, 'He brought him all of these, and divided them in the middle, and laid each half opposite the other; but he didn''t divide the birds.'),
  ('8387e150-458e-5d48-af49-6c726df0fd41', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 11, 11, 'The birds of prey came down on the carcasses, and Abram drove them away.'),
  ('f455e77d-1e42-5c1c-aef5-11b6bf382ea5', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 12, 12, 'When the sun was going down, a deep sleep fell on Abram. Now terror and great darkness fell on him.'),
  ('67583ad2-b7be-54d2-a3fc-1b81ae8da070', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 13, 13, 'He said to Abram, "Know for sure that your seed will live as foreigners in a land that is not theirs, and will serve them. They will afflict them four hundred years.'),
  ('7367e5c0-9b5b-5dde-a4c7-ee7ca62b792a', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 14, 14, 'I will also judge that nation, whom they will serve. Afterward they will come out with great wealth,'),
  ('5e5dd38e-cc43-5aa1-ae5c-50f4bb43ed2f', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 15, 15, 'but you will go to your fathers in peace. You will be buried in a good old age.'),
  ('f389e9fc-11c3-59e9-a104-35561b74b205', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 16, 16, 'In the fourth generation they will come here again, for the iniquity of the Amorite is not yet full."'),
  ('70da5a81-6267-5ad4-a35e-260aee8b6158', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 17, 17, 'It came to pass that, when the sun went down, and it was dark, behold, a smoking furnace, and a flaming torch passed between these pieces.'),
  ('fa9d9c24-55e6-57ea-a0a3-a719a85a98ce', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 18, 18, 'In that day Yahweh made a covenant with Abram, saying, "To your seed I have given this land, from the river of Egypt to the great river, the river Euphrates:'),
  ('5dca8c89-efda-5d36-ad8e-ea6bf738e79a', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 19, 19, 'the Kenites, the Kenizzites, the Kadmonites,'),
  ('a1ddd1ab-21d3-5f4d-affa-5c248f6f3ecb', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 20, 20, 'the Hittites, the Perizzites, the Rephaim,'),
  ('ebd22c8c-ef53-5fa4-aa07-45d732673d97', 'aefc05a3-e9b8-5d23-a4bf-c077cfecdad0', NULL, 21, 21, 'the Amorites, the Canaanites, the Girgashites, and the Jebusites."'),
  ('a2a1ebb5-c8e1-56f5-ada4-0e76be3a0bc5', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 1, 1, 'Now Sarai, Abram''s wife, bore him no children. She had a handmaid, an Egyptian, whose name was Hagar.'),
  ('e5fd69fe-d5ce-59b7-aabd-d1ba4e09175f', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 2, 2, 'Sarai said to Abram, "See now, Yahweh has restrained me from bearing. Please go in to my handmaid. It may be that I will obtain children by her." Abram listened to the voice of Sarai.'),
  ('09096c73-f42a-5457-ad39-820a50fdfad7', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 3, 3, 'Sarai, Abram''s wife, took Hagar the Egyptian, her handmaid, after Abram had lived ten years in the land of Canaan, and gave her to Abram her husband to be his wife.'),
  ('8f7754fa-3a7b-54c7-a780-a58082ce5ca0', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 4, 4, 'He went in to Hagar, and she conceived. When she saw that she had conceived, her mistress was despised in her eyes.'),
  ('6c7a43bf-28de-5855-a772-48a616259e00', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 5, 5, 'Sarai said to Abram, "This wrong is your fault. I gave my handmaid into your bosom, and when she saw that she had conceived, I was despised in her eyes. Yahweh judge between me and you."'),
  ('5aea228f-9ac5-519d-a598-852e3cd5a815', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 6, 6, 'But Abram said to Sarai, "Behold, your maid is in your hand. Do to her whatever is good in your eyes." Sarai dealt harshly with her, and she fled from her face.'),
  ('2a724c3f-cb8f-5b72-a400-42fbd9c15d8f', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 7, 7, 'The angel of Yahweh found her by a fountain of water in the wilderness, by the fountain in the way to Shur.'),
  ('e1063025-de0a-5414-a435-1f78a7fd7df5', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 8, 8, 'He said, "Hagar, Sarai''s handmaid, where did you come from? Where are you going?" She said, "I am fleeing from the face of my mistress Sarai."'),
  ('48fd1297-5284-5bdb-aef2-fbd8454a50f2', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 9, 9, 'The angel of Yahweh said to her, "Return to your mistress, and submit yourself under her hands."'),
  ('afe829d3-0a28-58b9-ad8b-37504f14a433', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 10, 10, 'The angel of Yahweh said to her, "I will greatly multiply your seed, that they will not be numbered for multitude."'),
  ('77d6e1af-93d2-5e2a-a962-8b187c76dd52', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 11, 11, 'The angel of Yahweh said to her, "Behold, you are with child, and will bear a son. You shall call his name Ishmael, because Yahweh has heard your affliction.'),
  ('0c1d1d53-ed2c-58e1-a175-6369627eaed6', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 12, 12, 'He will be like a wild donkey among men. His hand will be against every man, and every man''s hand against him. He will live opposite all of his brothers."'),
  ('891ceec6-d82c-5a8f-acfa-58442a14027e', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 13, 13, 'She called the name of Yahweh who spoke to her, "You are a God who sees," for she said, "Have I even stayed alive after seeing him?"'),
  ('e85cd078-d15f-5c9a-a702-55a3b3dd2691', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 14, 14, 'Therefore the well was called Beer Lahai Roi. Behold, it is between Kadesh and Bered.'),
  ('7663d01d-38a9-5f1f-ab79-1fe642401291', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 15, 15, 'Hagar bore a son for Abram. Abram called the name of his son, whom Hagar bore, Ishmael.'),
  ('6c0d0839-a5da-58c2-aa70-4dcb9eb083da', '4be5b8ac-a78c-5f2a-aee1-716702e82af9', NULL, 16, 16, 'Abram was eighty-six years old when Hagar bore Ishmael to Abram.'),
  ('67f4618a-a1a8-5419-ab13-5dfafb1d7cc3', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 1, 1, 'When Abram was ninety-nine years old, Yahweh appeared to Abram, and said to him, "I am God Almighty. Walk before me, and be blameless.'),
  ('ded14b83-77af-5128-a07c-92a42a2503b0', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 2, 2, 'I will make my covenant between me and you, and will multiply you exceedingly."'),
  ('27e9cc74-a2a3-5785-abd6-2b80ed449f75', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 3, 3, 'Abram fell on his face. God talked with him, saying,'),
  ('67a0b884-216c-5a34-af27-e12f73f4a8a4', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 4, 4, '"As for me, behold, my covenant is with you. You will be the father of a multitude of nations.'),
  ('c25d6c0e-e0b6-55ca-a5de-63205ea3be2d', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 5, 5, 'Neither will your name any more be called Abram, but your name will be Abraham; for I have made you the father of a multitude of nations.'),
  ('f4201701-7cda-55f2-a653-99ccdc14540f', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 6, 6, 'I will make you exceedingly fruitful, and I will make nations of you. Kings will come out of you.'),
  ('d96c03d7-f568-5259-ae39-df9d4415f0c4', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 7, 7, 'I will establish my covenant between me and you and your seed after you throughout their generations for an everlasting covenant, to be a God to you and to your seed after you.'),
  ('f15e5f09-f5fd-5484-aa30-a7b36c9243f7', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 8, 8, 'I will give to you, and to your seed after you, the land where you are traveling, all the land of Canaan, for an everlasting possession. I will be their God."'),
  ('0ea87ae7-0cee-5398-a333-9474cd1c41f9', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 9, 9, 'God said to Abraham, "As for you, you will keep my covenant, you and your seed after you throughout their generations.'),
  ('c8b2e2b8-4543-583b-ab78-e82a98b80af0', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 10, 10, 'This is my covenant, which you shall keep, between me and you and your seed after you. Every male among you shall be circumcised.'),
  ('de0884e6-f2a1-5b1e-a616-576ddffe0a0a', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 11, 11, 'You shall be circumcised in the flesh of your foreskin. It will be a token of the covenant between me and you.'),
  ('5dc0ce3a-8b2f-50e5-a00f-39cb415d1120', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 12, 12, 'He who is eight days old will be circumcised among you, every male throughout your generations, he who is born in the house, or bought with money from any foreigner who is not of your seed.'),
  ('814f3dec-5bdc-54df-ad1b-70c451d4c737', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 13, 13, 'He who is born in your house, and he who is bought with your money, must be circumcised. My covenant will be in your flesh for an everlasting covenant.'),
  ('c9cf26a7-f6e6-5bab-a413-268621397f47', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 14, 14, 'The uncircumcised male who is not circumcised in the flesh of his foreskin, that soul shall be cut off from his people. He has broken my covenant."'),
  ('582e2bb8-5042-527c-a098-05aa923cfecc', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 15, 15, 'God said to Abraham, "As for Sarai your wife, you shall not call her name Sarai, but her name will be Sarah.'),
  ('6dd6fdeb-0c2b-5e72-aadd-b217d4eaeafe', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 16, 16, 'I will bless her, and moreover I will give you a son by her. Yes, I will bless her, and she will be a mother of nations. Kings of peoples will come from her."'),
  ('c64f0924-7f96-55ee-a0e1-60c86efaafec', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 17, 17, 'Then Abraham fell on his face, and laughed, and said in his heart, "Will a child be born to him who is one hundred years old? Will Sarah, who is ninety years old, give birth?"'),
  ('b80b3262-a310-5d3b-ab38-d398e02fb481', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 18, 18, 'Abraham said to God, "Oh that Ishmael might live before you!"'),
  ('4a2ae513-d6fc-5e92-a4b5-987e66cc75d0', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 19, 19, 'God said, "No, but Sarah, your wife, will bear you a son. You shall call his name Isaac. I will establish my covenant with him for an everlasting covenant for his seed after him.'),
  ('11cabcd2-c938-56d0-adf4-eba59b98b8e2', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 20, 20, 'As for Ishmael, I have heard you. Behold, I have blessed him, and will make him fruitful, and will multiply him exceedingly. He will become the father of twelve princes, and I will make him a great nation.'),
  ('c8d59ac5-0f57-5545-ad4f-7c9c948365df', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 21, 21, 'But my covenant I establish with Isaac, whom Sarah will bear to you at this set time next year."'),
  ('a740cee2-a70e-5758-a67b-bc97e12f5018', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 22, 22, 'When he finished talking with him, God went up from Abraham.'),
  ('69be44cc-bcb5-521f-a1cb-02960c7e3f89', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 23, 23, 'Abraham took Ishmael his son, all who were born in his house, and all who were bought with his money; every male among the men of Abraham''s house, and circumcised the flesh of their foreskin in the same day, as God had said to him.'),
  ('3a3c1a56-dc23-5bb5-affd-ac784e64f16a', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 24, 24, 'Abraham was ninety-nine years old, when he was circumcised in the flesh of his foreskin.'),
  ('45c599c3-0c6a-5ef8-a91d-2648dde7ca64', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 25, 25, 'Ishmael, his son, was thirteen years old when he was circumcised in the flesh of his foreskin.'),
  ('c65b6920-7482-54b0-ab62-b4dae22641de', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 26, 26, 'In the same day both Abraham and Ishmael, his son, were circumcised.'),
  ('6c10e457-1f2e-54d0-a68a-1ea1d259579a', 'e3e5a08b-a90f-5e59-ab87-9a1ed9efd929', NULL, 27, 27, 'All the men of his house, those born in the house, and those bought with money of a foreigner, were circumcised with him.'),
  ('85a26ee0-20fe-58c3-a0a3-a84b3b46702c', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 1, 1, 'Yahweh appeared to him by the oaks of Mamre, as he sat in the tent door in the heat of the day.'),
  ('dd6e8230-35ec-51df-a926-dafa7e231637', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 2, 2, 'He lifted up his eyes and looked, and saw that three men stood opposite him. When he saw them, he ran to meet them from the tent door, and bowed himself to the earth,'),
  ('56b9c6a6-3188-5efc-a3e5-81ae973afc42', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 3, 3, 'and said, "My lord, if now I have found favor in your sight, please don''t go away from your servant.'),
  ('68afe21b-157b-5076-a7ec-4edf6335199e', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 4, 4, 'Now let a little water be fetched, wash your feet, and rest yourselves under the tree.'),
  ('15819c78-c8f3-51e1-ae25-74c37a6043c3', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 5, 5, 'I will get a morsel of bread so you can refresh your heart. After that you may go your way, now that you have come to your servant." They said, "Very well, do as you have said."'),
  ('9e648e20-63fb-5b3f-a916-eff93daf6fef', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 6, 6, 'Abraham hurried into the tent to Sarah, and said, "Quickly prepare three measures of fine meal, knead it, and make cakes."'),
  ('a024cdb4-f7a4-553a-a860-602a7658cff8', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 7, 7, 'Abraham ran to the herd, and fetched a tender and good calf, and gave it to the servant. He hurried to dress it.'),
  ('dee9ca46-0810-5914-aad2-3e53771011c5', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 8, 8, 'He took butter, milk, and the calf which he had dressed, and set it before them. He stood by them under the tree, and they ate.'),
  ('0d7a373f-1ea5-5049-a203-10425565626d', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 9, 9, 'They asked him, "Where is Sarah, your wife?" He said, "See, in the tent."'),
  ('6ff02b38-403f-59ef-a026-195bba0a183e', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 10, 10, 'He said, "I will certainly return to you when the season comes round. Behold, Sarah your wife will have a son." Sarah heard in the tent door, which was behind him.'),
  ('b49a51b5-d8e5-55da-a221-d93db59c3266', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 11, 11, 'Now Abraham and Sarah were old, well advanced in age. Sarah had passed the age of childbearing.'),
  ('2e4dfa19-cf7d-54b6-a809-bb6fbea81bb2', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 12, 12, 'Sarah laughed within herself, saying, "After I have grown old will I have pleasure, my lord being old also?"'),
  ('3bccc66b-50e6-575b-aa8d-606f144f5ed9', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 13, 13, 'Yahweh said to Abraham, "Why did Sarah laugh, saying, ''Will I really bear a child, yet I am old?'''),
  ('489cfe6a-45f4-5007-a966-42b09245952f', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 14, 14, 'Is anything too hard for Yahweh? At the set time I will return to you, when the season comes round, and Sarah will have a son."'),
  ('fd55d58f-4d57-545e-ac50-ae7bb3aaa7b2', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 15, 15, 'Then Sarah denied, saying, "I didn''t laugh," for she was afraid. He said, "No, but you did laugh."'),
  ('dd7d927d-6e8f-5008-aac9-6b5f211dab7b', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 16, 16, 'The men rose up from there, and looked toward Sodom. Abraham went with them to see them on their way.'),
  ('13178780-28f5-5090-af4a-4fc68777a2bd', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 17, 17, 'Yahweh said, "Will I hide from Abraham what I do,'),
  ('7550c0bf-0995-5c2c-a4c3-22f5eaa4c871', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 18, 18, 'since Abraham has surely become a great and mighty nation, and all the nations of the earth will be blessed in him?'),
  ('7e57aeae-5217-50a2-ae7b-11406afedcfa', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 19, 19, 'For I have known him, to the end that he may command his children and his household after him, that they may keep the way of Yahweh, to do righteousness and justice; to the end that Yahweh may bring on Abraham that which he has spoken of him."'),
  ('69aa4666-4b1c-543f-a1af-e7adb12d6d41', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 20, 20, 'Yahweh said, "Because the cry of Sodom and Gomorrah is great, and because their sin is very grievous,'),
  ('cfc68ebb-01f7-5565-adfb-8ea0a929f165', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 21, 21, 'I will go down now, and see whether their deeds are as bad as the reports which have come to me. If not, I will know."'),
  ('2a79eac1-ab3f-599e-a1a3-ca74a44d0c3f', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 22, 22, 'The men turned from there, and went toward Sodom, but Abraham stood yet before Yahweh.'),
  ('6c7e60e9-7d7b-5018-a6f8-dacc082d39aa', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 23, 23, 'Abraham drew near, and said, "Will you consume the righteous with the wicked?'),
  ('f7c10702-d4bd-5dbc-a4ba-67ea89ac78b2', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 24, 24, 'What if there are fifty righteous within the city? Will you consume and not spare the place for the fifty righteous who are in it?'),
  ('8e768d6f-9775-5d35-ad84-5d52bb4ab898', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 25, 25, 'Be it far from you to do things like that, to kill the righteous with the wicked, so that the righteous should be like the wicked. May that be far from you. Shouldn''t the Judge of all the earth do right?"'),
  ('2dbed15b-1bb8-5cd7-a6ec-74a517c8f10e', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 26, 26, 'Yahweh said, "If I find in Sodom fifty righteous within the city, then I will spare all the place for their sake."'),
  ('8abdb695-3628-57a7-aecb-986176056602', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 27, 27, 'Abraham answered, "See now, I have taken it on myself to speak to the Lord, who am but dust and ashes.'),
  ('c7a75830-013f-587a-af7c-02b1954a6a54', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 28, 28, 'What if there will lack five of the fifty righteous? Will you destroy all the city for lack of five?" He said, "I will not destroy it, if I find forty-five there."'),
  ('aa2c5a1a-2986-5654-abd9-885db94715bb', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 29, 29, 'He spoke to him yet again, and said, "What if there are forty found there?" He said, "I will not do it for the forty''s sake."'),
  ('66c1479c-cb36-5d17-abc0-ec3530ceee6a', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 30, 30, 'He said, "Oh don''t let the Lord be angry, and I will speak. What if there are thirty found there?" He said, "I will not do it, if I find thirty there."'),
  ('0b0263d8-7354-5027-a450-8e188d23fcec', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 31, 31, 'He said, "See now, I have taken it on myself to speak to the Lord. What if there are twenty found there?" He said, "I will not destroy it for the twenty''s sake."'),
  ('96c1d2b5-3511-579f-a956-652e4613890a', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 32, 32, 'He said, "Oh don''t let the Lord be angry, and I will speak just once more. What if ten are found there?" He said, "I will not destroy it for the ten''s sake."'),
  ('b1b6b53f-302d-599f-a973-93015f8eb887', '8e2e3c0b-a4c7-565b-aca2-011cd1aa1705', NULL, 33, 33, 'Yahweh went his way, as soon as he had finished communing with Abraham, and Abraham returned to his place.'),
  ('c7052564-3846-53ce-a4ee-4d15df89b7fb', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 1, 1, 'The two angels came to Sodom at evening. Lot sat in the gate of Sodom. Lot saw them, and rose up to meet them. He bowed himself with his face to the earth,'),
  ('e34eba37-81ab-574d-ae28-f8df2f9c70d3', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 2, 2, 'and he said, "See now, my lords, please turn aside into your servant''s house, stay all night, wash your feet, and you can rise up early, and go on your way." They said, "No, but we will stay in the street all night."'),
  ('d3b4b947-f923-55c5-a36a-9eea0edc8343', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 3, 3, 'He urged them greatly, and they came in with him, and entered into his house. He made them a feast, and baked unleavened bread, and they ate.'),
  ('5204af86-7ebb-54a7-a1a9-484357d2ae5c', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 4, 4, 'But before they lay down, the men of the city, the men of Sodom, surrounded the house, both young and old, all the people from every quarter.'),
  ('39b08c33-9ede-5e47-af72-9b5fa58609c0', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 5, 5, 'They called to Lot, and said to him, "Where are the men who came in to you this night? Bring them out to us, that we may have sex with them."'),
  ('574c314f-0aad-5377-a615-29ce61eabc82', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 6, 6, 'Lot went out to them to the door, and shut the door after him.'),
  ('e4fb6104-2602-51f8-a3f3-3006a1507cc5', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 7, 7, 'He said, "Please, my brothers, don''t act so wickedly.'),
  ('b0641c53-c2d2-501a-a7bb-b532d1b5c2ea', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 8, 8, 'See now, I have two virgin daughters. Please let me bring them out to you, and you may do to them what seems good to you. Only don''t do anything to these men, because they have come under the shadow of my roof."'),
  ('953f9984-e054-5a35-a794-cfe5ae594a89', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 9, 9, 'They said, "Stand back!" Then they said, "This one fellow came in to live as a foreigner, and he appoints himself a judge. Now will we deal worse with you, than with them!" They pressed hard on the man Lot, and drew near to break the door.'),
  ('2d9ab8d2-509a-5fb8-a04e-7bc4b15140ae', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 10, 10, 'But the men put forth their hand, and brought Lot into the house to them, and shut the door.'),
  ('2148cb54-2625-56d9-a48b-940457ab58ec', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 11, 11, 'They struck the men who were at the door of the house with blindness, both small and great, so that they wearied themselves to find the door.'),
  ('323ab5bc-f8d7-5c88-a4b7-ece8da48858a', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 12, 12, 'The men said to Lot, "Do you have anybody else here? Sons-in-law, your sons, your daughters, and whoever you have in the city, bring them out of the place:'),
  ('885bb0d6-5c00-58d9-aa8f-e562a74c06c0', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 13, 13, 'for we will destroy this place, because the outcry against them has grown great before Yahweh that Yahweh has sent us to destroy it."'),
  ('b46d8994-a96a-5bec-ac74-f4fd63adee7d', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 14, 14, 'Lot went out, and spoke to his sons-in-law, who were pledged to marry his daughters, and said, "Get up! Get out of this place, for Yahweh will destroy the city." But he seemed to his sons-in-law to be joking.'),
  ('ebe17b60-feb9-525b-a673-77d3a9362b35', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 15, 15, 'When the morning came, then the angels hurried Lot, saying, "Get up! Take your wife, and your two daughters who are here, lest you be consumed in the iniquity of the city."'),
  ('036a4543-e12c-5ffb-a900-da7dd81ab494', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 16, 16, 'But he lingered; and the men grabbed his hand, his wife''s hand, and his two daughters'' hands, Yahweh being merciful to him; and they took him out, and set him outside of the city.'),
  ('8523cd3f-dc7c-55b7-a54f-15bc82a26794', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 17, 17, 'It came to pass, when they had taken them out, that he said, "Escape for your life! Don''t look behind you, and don''t stay anywhere in the plain. Escape to the mountains, lest you be consumed!"'),
  ('903525e8-7cfe-5244-add8-d1c6b8331a96', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 18, 18, 'Lot said to them, "Oh, not so, my lord.'),
  ('9ea9957d-7a40-5e88-a5a6-52c9e6f0e7e4', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 19, 19, 'See now, your servant has found favor in your sight, and you have magnified your loving kindness, which you have shown to me in saving my life. I can''t escape to the mountain, lest evil overtake me, and I die.'),
  ('a4367418-1309-566b-aa6f-3f241871e5c1', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 20, 20, 'See now, this city is near to flee to, and it is a little one. Oh let me escape there (isn''t it a little one?), and my soul will live."'),
  ('507ae0b6-3f01-5a38-aa62-8aa9e25456a8', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 21, 21, 'He said to him, "Behold, I have granted your request concerning this thing also, that I will not overthrow the city of which you have spoken.'),
  ('d29ad848-9bca-59a7-a941-7dad7e7e499d', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 22, 22, 'Hurry, escape there, for I can''t do anything until you get there." Therefore the name of the city was called Zoar.'),
  ('840a0fba-142e-55dc-a5d4-a48aa751bf74', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 23, 23, 'The sun had risen on the earth when Lot came to Zoar.'),
  ('10926a3b-de83-5810-ac46-f926e6ad863e', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 24, 24, 'Then Yahweh rained on Sodom and on Gomorrah sulfur and fire from Yahweh out of the sky.'),
  ('dc42be61-d57e-599c-adde-bec90b42ba39', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 25, 25, 'He overthrew those cities, all the plain, all the inhabitants of the cities, and that which grew on the ground.'),
  ('396a0fa0-3f69-5e50-a4be-cf05011777d4', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 26, 26, 'But his wife looked back from behind him, and she became a pillar of salt.'),
  ('d940dc4f-ff02-5103-aa4c-0910ca933698', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 27, 27, 'Abraham got up early in the morning to the place where he had stood before Yahweh.'),
  ('ce6e0f4c-1cf8-56a5-ae3a-abd6136cd6b2', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 28, 28, 'He looked toward Sodom and Gomorrah, and toward all the land of the plain, and looked, and saw that the smoke of the land went up as the smoke of a furnace.'),
  ('1ffa734b-d25f-5416-a504-ae4db457dbae', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 29, 29, 'It happened, when God destroyed the cities of the plain, that God remembered Abraham, and sent Lot out of the middle of the overthrow, when he overthrew the cities in which Lot lived.'),
  ('0df713d2-96e0-5088-a7aa-4489ceac9511', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 30, 30, 'Lot went up out of Zoar, and lived in the mountain, and his two daughters with him; for he was afraid to live in Zoar. He lived in a cave with his two daughters.'),
  ('55e882f6-9842-5d1a-ab62-18254b49c4c0', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 31, 31, 'The firstborn said to the younger, "Our father is old, and there is not a man in the earth to come in to us in the way of all the earth.'),
  ('47901de2-598d-5f38-ac67-0438a2cac568', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 32, 32, 'Come, let''s make our father drink wine, and we will lie with him, that we may preserve our father''s seed."'),
  ('90e45fec-7a8e-59be-aa9a-e6a326b7d778', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 33, 33, 'They made their father drink wine that night: and the firstborn went in, and lay with her father. He didn''t know when she lay down, nor when she arose.'),
  ('9366b3f6-7f64-5c2f-a10c-db26961c97b3', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 34, 34, 'It came to pass on the next day, that the firstborn said to the younger, "Behold, I lay last night with my father. Let us make him drink wine again, tonight. You go in, and lie with him, that we may preserve our father''s seed."'),
  ('986b47c3-099c-5005-a90c-b3588378ff9c', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 35, 35, 'They made their father drink wine that night also. The younger went and lay with him. He didn''t know when she lay down, nor when she got up.'),
  ('581519b4-d6c1-5e86-aea7-7d928b34fe50', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 36, 36, 'Thus both of Lot''s daughters were with child by their father.'),
  ('e4170fd2-0655-5702-af0b-e6e8b2fc66a1', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 37, 37, 'The firstborn bore a son, and named him Moab. He is the father of the Moabites to this day.'),
  ('eb4e8b48-8f8d-5424-a5f0-7547e6b838e8', '3db920c1-f1f9-54f0-a64b-64b0e83182ee', NULL, 38, 38, 'The younger also bore a son, and called his name Ben Ammi. He is the father of the children of Ammon to this day.'),
  ('b3b91ad7-21d3-58d0-a278-7ed5d4efc093', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 1, 1, 'Abraham traveled from there toward the land of the South, and lived between Kadesh and Shur. He lived as a foreigner in Gerar.'),
  ('d8d56591-1ab7-5d34-ab41-d76d25585153', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 2, 2, 'Abraham said about Sarah his wife, "She is my sister." Abimelech king of Gerar sent, and took Sarah.'),
  ('7478d303-c185-5aeb-ac17-ea067bb55239', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 3, 3, 'But God came to Abimelech in a dream of the night, and said to him, "Behold, you are a dead man, because of the woman whom you have taken. For she is a man''s wife."'),
  ('33175c14-d201-57bd-a6ae-2a4d5fcf88a8', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 4, 4, 'Now Abimelech had not come near her. He said, "Lord, will you kill even a righteous nation?'),
  ('a4db6423-4b6c-5c28-a2a1-0c90ca0ff5fa', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 5, 5, 'Didn''t he tell me, ''She is my sister?'' She, even she herself, said, ''He is my brother.'' In the integrity of my heart and the innocence of my hands have I done this."'),
  ('19bb3b7c-b467-5ada-a21d-dc9fee699f75', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 6, 6, 'God said to him in the dream, "Yes, I know that in the integrity of your heart you have done this, and I also withheld you from sinning against me. Therefore I didn''t allow you to touch her.'),
  ('5ba52d46-b8ea-59c8-a140-e2a3e9451702', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 7, 7, 'Now therefore, restore the man''s wife. For he is a prophet, and he will pray for you, and you will live. If you don''t restore her, know for sure that you will die, you, and all who are yours."'),
  ('bea8bb40-96fd-5249-a661-aa6f49d6078d', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 8, 8, 'Abimelech rose early in the morning, and called all his servants, and told all these things in their ear. The men were very scared.'),
  ('374cde18-8d14-57d8-a396-ab3aa632e809', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 9, 9, 'Then Abimelech called Abraham, and said to him, "What have you done to us? How have I sinned against you, that you have brought on me and on my kingdom a great sin? You have done deeds to me that ought not to be done!"'),
  ('c1d69728-2eb9-5378-a604-3eefb0e12504', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 10, 10, 'Abimelech said to Abraham, "What did you see, that you have done this thing?"'),
  ('ec256834-cb50-5836-abf5-80745a6e1d76', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 11, 11, 'Abraham said, "Because I thought, ''Surely the fear of God is not in this place. They will kill me for my wife''s sake.'''),
  ('5452cc6e-dd82-5925-a5b0-a92450748a16', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 12, 12, 'Besides, she is indeed my sister, the daughter of my father, but not the daughter of my mother; and she became my wife.'),
  ('a553b9f9-21ef-594d-a010-7a42d37098d9', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 13, 13, 'It happened, when God caused me to wander from my father''s house, that I said to her, ''This is your kindness which you shall show to me. Everywhere that we go, say of me, "He is my brother."''"'),
  ('6c4c8844-7a68-5076-af3f-5dd67af43e88', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 14, 14, 'Abimelech took sheep and cattle, male servants and female servants, and gave them to Abraham, and restored Sarah, his wife, to him.'),
  ('26d538bf-1734-55c7-aaa2-51d5223096bd', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 15, 15, 'Abimelech said, "Behold, my land is before you. Dwell where it pleases you."'),
  ('0af89d44-3a4c-5e08-aa23-1dec132a405a', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 16, 16, 'To Sarah he said, "Behold, I have given your brother a thousand pieces of silver. Behold, it is for you a covering of the eyes to all that are with you. In front of all you are vindicated."'),
  ('6721ee4a-7257-58bd-aad3-977fbcc59776', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 17, 17, 'Abraham prayed to God. God healed Abimelech, and his wife, and his female servants, and they bore children.'),
  ('c4e0930d-7fd1-554d-acf6-ab05bbd714c1', '13909d82-78b6-5660-a30e-59c3184e1fb0', NULL, 18, 18, 'For Yahweh had closed up tight all the wombs of the house of Abimelech, because of Sarah, Abraham''s wife.'),
  ('36926c49-a955-535b-a41d-163d1126af52', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 1, 1, 'Yahweh visited Sarah as he had said, and Yahweh did to Sarah as he had spoken.'),
  ('c31667d3-52df-5d75-a578-f285ec5653ef', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 2, 2, 'Sarah conceived, and bore Abraham a son in his old age, at the set time of which God had spoken to him.'),
  ('57e6ceae-8839-521e-a092-b4abda8b3322', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 3, 3, 'Abraham called his son who was born to him, whom Sarah bore to him, Isaac.'),
  ('ea89955d-2333-5658-a069-d84407751b5c', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 4, 4, 'Abraham circumcised his son, Isaac, when he was eight days old, as God had commanded him.'),
  ('dd182a29-00b0-556f-a0b1-484eb46934d4', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 5, 5, 'Abraham was one hundred years old when his son, Isaac, was born to him.'),
  ('87083fe4-d93d-597b-a2b7-67a7ba66b725', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 6, 6, 'Sarah said, "God has made me laugh. Everyone who hears will laugh with me."'),
  ('fa1f3d38-bb32-5686-a811-47f8c406562e', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 7, 7, 'She said, "Who would have said to Abraham, that Sarah would nurse children? For I have borne him a son in his old age."'),
  ('37ca0f9c-ec22-5f84-a42e-b40479e0a744', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 8, 8, 'The child grew, and was weaned. Abraham made a great feast on the day that Isaac was weaned.'),
  ('ce967f36-0d97-52fb-ab92-17c8767b0225', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 9, 9, 'Sarah saw the son of Hagar the Egyptian, whom she had borne to Abraham, mocking.'),
  ('9baf2e21-56a8-5349-a305-0f4ca1fe4763', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 10, 10, 'Therefore she said to Abraham, "Cast out this handmaid and her son! For the son of this handmaid will not be heir with my son, Isaac."'),
  ('caeeab23-4893-57a7-a715-d27d569778f9', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 11, 11, 'The thing was very grievous in Abraham''s sight on account of his son.'),
  ('da4ff057-247d-591c-a098-4d0a78057d9a', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 12, 12, 'God said to Abraham, "Don''t let it be grievous in your sight because of the boy, and because of your handmaid. In all that Sarah says to you, listen to her voice. For from Isaac will your seed be called.'),
  ('9a8a0daf-57e1-5a99-aa5f-dce497545301', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 13, 13, 'I will also make a nation of the son of the handmaid, because he is your seed."'),
  ('f3993ffd-1747-5bec-af3e-48c80ded5d56', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 14, 14, 'Abraham rose up early in the morning, and took bread and a bottle of water, and gave it to Hagar, putting it on her shoulder; and gave her the child, and sent her away. She departed, and wandered in the wilderness of Beersheba.'),
  ('dd3f643d-fd98-5594-a0be-f10b0dc87ba3', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 15, 15, 'The water in the bottle was spent, and she cast the child under one of the shrubs.'),
  ('e1e5513e-e1f1-5cda-a614-8381cdd675b4', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 16, 16, 'She went and sat down opposite him, a good way off, about a bow shot away. For she said, "Don''t let me see the death of the child." She sat over against him, and lifted up her voice, and wept.'),
  ('1836f79e-68f5-50e8-a083-a8329deac28c', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 17, 17, 'God heard the voice of the boy. The angel of God called to Hagar out of the sky, and said to her, "What ails you, Hagar? Don''t be afraid. For God has heard the voice of the boy where he is.'),
  ('b51097f7-d2d7-5b77-a236-2616101c9a20', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 18, 18, 'Get up, lift up the boy, and hold him in your hand. For I will make him a great nation."'),
  ('57da625d-c977-5753-a37c-b6147a46a447', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 19, 19, 'God opened her eyes, and she saw a well of water. She went, filled the bottle with water, and gave the boy drink.'),
  ('79314d45-2524-5483-aa64-93fa5f4bc98e', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 20, 20, 'God was with the boy, and he grew. He lived in the wilderness, and became, as he grew up, an archer.'),
  ('ec0e697e-c538-51d4-a5d7-118cea1f743c', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 21, 21, 'He lived in the wilderness of Paran. His mother took a wife for him out of the land of Egypt.'),
  ('01de4370-e730-512b-aaca-21b7fb3f927c', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 22, 22, 'It happened at that time, that Abimelech and Phicol the captain of his army spoke to Abraham, saying, "God is with you in all that you do.'),
  ('bd57ec38-1e43-52af-aed6-d7ce150721bf', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 23, 23, 'Now, therefore, swear to me here by God that you will not deal falsely with me, nor with my son, nor with my son''s son. But according to the kindness that I have done to you, you shall do to me, and to the land in which you have lived as a foreigner."'),
  ('9c69aacb-c420-5bb9-adb9-06c3505e2eb9', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 24, 24, 'Abraham said, "I will swear."'),
  ('dce26f24-24b1-57ef-a7a4-c86346fed892', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 25, 25, 'Abraham complained to Abimelech because of a water well, which Abimelech''s servants had violently taken away.'),
  ('cd302335-29be-5e57-a342-155a56a40870', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 26, 26, 'Abimelech said, "I don''t know who has done this thing. Neither did you tell me, neither did I hear of it, until today."'),
  ('b3dccc10-4e41-50ba-aa9d-f04bcd04bcf0', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 27, 27, 'Abraham took sheep and cattle, and gave them to Abimelech. Those two made a covenant.'),
  ('eb10310b-72e0-53f8-aa74-0e9c2248b8cc', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 28, 28, 'Abraham set seven ewe lambs of the flock by themselves.'),
  ('aa487488-53cb-54f7-ae3b-8a4821e80b2c', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 29, 29, 'Abimelech said to Abraham, "What do these seven ewe lambs which you have set by themselves mean?"'),
  ('35ae7631-d1bf-573d-af83-2fd6d71a2834', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 30, 30, 'He said, "You shall take these seven ewe lambs from my hand, that it may be a witness to me, that I have dug this well."'),
  ('9315206e-16b7-5b05-a6af-3c720656fa3b', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 31, 31, 'Therefore he called that place Beersheba, because they both swore there.'),
  ('5444985f-a618-5fd3-a3b7-081a197776ca', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 32, 32, 'So they made a covenant at Beersheba. Abimelech rose up with Phicol, the captain of his army, and they returned into the land of the Philistines.'),
  ('ddcdc8d1-c1d4-5c29-a067-3d1e50c19fa2', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 33, 33, 'Abraham planted a tamarisk tree in Beersheba, and called there on the name of Yahweh, the Everlasting God.'),
  ('485b19dc-eaa3-5cd6-a6b0-7d57356a7e9d', '518c2ba4-e158-5a5a-ad0d-bd87d7eeda8f', NULL, 34, 34, 'Abraham lived as a foreigner in the land of the Philistines many days.'),
  ('9226a637-8cd1-5510-a318-d95d162aa4ae', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 1, 1, 'It happened after these things, that God tested Abraham, and said to him, "Abraham!" He said, "Here I am."'),
  ('def99ec0-a5be-587b-afba-6519e9025124', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 2, 2, 'He said, "Now take your son, your only son, whom you love, even Isaac, and go into the land of Moriah. Offer him there for a burnt offering on one of the mountains which I will tell you of."'),
  ('62b4dec5-dfa3-5b6b-a6c5-1033b3cc8428', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 3, 3, 'Abraham rose early in the morning, and saddled his donkey, and took two of his young men with him, and Isaac his son. He split the wood for the burnt offering, and rose up, and went to the place of which God had told him.'),
  ('654369fe-173c-54bd-ad0b-4653cc0f4a11', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 4, 4, 'On the third day Abraham lifted up his eyes, and saw the place far off.'),
  ('f89d2709-c0a3-581b-aaed-392053cd960a', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 5, 5, 'Abraham said to his young men, "Stay here with the donkey. The boy and I will go yonder. We will worship, and come back to you."'),
  ('2d5b4c2f-c1f0-5e91-ac5f-7bfaadf8ebc4', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 6, 6, 'Abraham took the wood of the burnt offering and laid it on Isaac his son. He took in his hand the fire and the knife. They both went together.'),
  ('22b2e549-e461-5aca-a82d-4f14485eb18e', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 7, 7, 'Isaac spoke to Abraham his father, and said, "My father?" He said, "Here I am, my son." He said, "Here is the fire and the wood, but where is the lamb for a burnt offering?"'),
  ('1c49df97-9889-542d-a40a-d507e379bd80', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 8, 8, 'Abraham said, "God will provide himself the lamb for a burnt offering, my son." So they both went together.'),
  ('372119c4-d2cf-5726-a4e0-75cc6fd895ee', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 9, 9, 'They came to the place which God had told him of. Abraham built the altar there, and laid the wood in order, bound Isaac his son, and laid him on the altar, on the wood.'),
  ('9c59820e-c443-5d48-af27-367120739602', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 10, 10, 'Abraham stretched forth his hand, and took the knife to kill his son.'),
  ('49e17f45-9db1-5818-acf5-9df5c3fef7bb', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 11, 11, 'The angel of Yahweh called to him out of the sky, and said, "Abraham, Abraham!" He said, "Here I am."'),
  ('63c13cba-7e5d-57fe-a759-4be05a6168c1', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 12, 12, 'He said, "Don''t lay your hand on the boy, neither do anything to him. For now I know that you fear God, since you have not withheld your son, your only son, from me."'),
  ('1b4614f1-aedb-5bc8-a3f1-ec386402bd59', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 13, 13, 'Abraham lifted up his eyes, and looked, and saw that behind him was a ram caught in the thicket by his horns. Abraham went and took the ram, and offered him up for a burnt offering instead of his son.'),
  ('fafcb4a8-23e6-521a-ac66-ca2d8c98e6fa', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 14, 14, 'Abraham called the name of that place Yahweh Will Provide. As it is said to this day, "On Yahweh''s mountain, it will be provided."'),
  ('da0dc972-57d7-5dbd-a0d1-d6cf06948cb3', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 15, 15, 'The angel of Yahweh called to Abraham a second time out of the sky,'),
  ('5005b7ca-2f1f-523d-abcd-fae801dc460d', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 16, 16, 'and said, "I have sworn by myself, says Yahweh, because you have done this thing, and have not withheld your son, your only son,'),
  ('ecfe3e9e-417d-59d4-a501-c3dcc36ae003', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 17, 17, 'that I will bless you greatly, and I will multiply your seed greatly like the stars of the heavens, and like the sand which is on the seashore. Your seed will possess the gate of his enemies.'),
  ('24f281c8-d0f1-5f2e-a52d-c1a345a9ab92', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 18, 18, 'In your seed will all the nations of the earth be blessed, because you have obeyed my voice."'),
  ('011c2f0d-83c5-5cfa-ab5c-288817b0a04b', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 19, 19, 'So Abraham returned to his young men, and they rose up and went together to Beersheba. Abraham lived at Beersheba.'),
  ('4c686ae7-b827-5381-a44a-f1924501c539', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 20, 20, 'It happened after these things, that it was told Abraham, saying, "Behold, Milcah, she also has borne children to your brother Nahor:'),
  ('5c1a19da-5d7e-54eb-a41f-00899ad39502', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 21, 21, 'Uz his firstborn, Buz his brother, Kemuel the father of Aram,'),
  ('e5a7d500-b2aa-5288-a1db-4546cb152912', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 22, 22, 'Chesed, Hazo, Pildash, Jidlaph, and Bethuel."'),
  ('2b3c3c77-c1b9-5d32-a747-1d7e2f2f01a5', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 23, 23, 'Bethuel became the father of Rebekah. These eight Milcah bore to Nahor, Abraham''s brother.'),
  ('47ad0732-a514-5936-af11-bea57f1e20aa', '492f2db1-52e2-5620-a0aa-43bc0f85c07a', NULL, 24, 24, 'His concubine, whose name was Reumah, also bore Tebah, Gaham, Tahash, and Maacah.'),
  ('8c02b87c-b2a4-5b70-ab5e-1ba80fe202d2', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 1, 1, 'Sarah lived one hundred twenty-seven years. This was the length of Sarah''s life.'),
  ('4a5ab8ab-da4c-5642-a339-317f85f71ebf', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 2, 2, 'Sarah died in Kiriath Arba (the same is Hebron), in the land of Canaan. Abraham came to mourn for Sarah, and to weep for her.'),
  ('fbfee558-1416-5a83-a525-77a231706bd8', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 3, 3, 'Abraham rose up from before his dead, and spoke to the children of Heth, saying,'),
  ('a0282462-fefc-543f-a692-4efe77de593e', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 4, 4, '"I am a stranger and a foreigner living with you. Give me a possession of a burying-place with you, that I may bury my dead out of my sight."'),
  ('f68d80f4-e96d-5506-a878-a62f3b3e735f', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 5, 5, 'The children of Heth answered Abraham, saying to him,'),
  ('a3232a0d-f822-5f2d-a764-5a097f1a897b', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 6, 6, '"Hear us, my lord. You are a prince of God among us. Bury your dead in the best of our tombs. None of us will withhold from you his tomb. Bury your dead."'),
  ('ebe7f40a-78d0-5f41-aca1-b4e972b42734', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 7, 7, 'Abraham rose up, and bowed himself to the people of the land, even to the children of Heth.'),
  ('3284da1a-9e2b-5c4b-a0cf-191685a3633b', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 8, 8, 'He talked with them, saying, "If it be your mind that I should bury my dead out of my sight, hear me, and entreat for me to Ephron the son of Zohar,'),
  ('fc043556-6351-5a8e-a4e6-b60daa89ee6e', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 9, 9, 'that he may give me the cave of Machpelah, which he has, which is in the end of his field. For the full price let him give it to me among you for a possession of a burying-place."'),
  ('c65d6ae2-0412-5f65-aa04-52cf1c208118', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 10, 10, 'Now Ephron was sitting in the middle of the children of Heth. Ephron the Hittite answered Abraham in the hearing of the children of Heth, even of all who went in at the gate of his city, saying,'),
  ('a522cb4c-6ffe-537a-ad83-4e38f682e3ea', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 11, 11, '"No, my lord, hear me. I give you the field, and I give you the cave that is in it. In the presence of the children of my people I give it to you. Bury your dead."'),
  ('81db94f8-7f58-5420-a925-5b590deb5701', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 12, 12, 'Abraham bowed himself down before the people of the land.'),
  ('0e038a56-ecff-55b2-a53d-089b107f5e4c', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 13, 13, 'He spoke to Ephron in the audience of the people of the land, saying, "But if you will, please hear me. I will give the price of the field. Take it from me, and I will bury my dead there."'),
  ('2537eced-4033-5ce9-aa27-eae973c6861a', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 14, 14, 'Ephron answered Abraham, saying to him,'),
  ('e5d9443e-dca8-5ae7-af2f-0b00793ecaa0', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 15, 15, '"My lord, listen to me. What is a piece of land worth four hundred shekels of silver between me and you? Therefore bury your dead."'),
  ('57656098-f16e-5b79-a85b-245bdb2ba027', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 16, 16, 'Abraham listened to Ephron. Abraham weighed to Ephron the silver which he had named in the audience of the children of Heth, four hundred shekels of silver, according to the current merchants'' standard.'),
  ('3eaaa49b-a4f0-5659-aab7-648438182b1c', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 17, 17, 'So the field of Ephron, which was in Machpelah, which was before Mamre, the field, the cave which was in it, and all the trees that were in the field, that were in all of its borders, were deeded'),
  ('e999de3a-21de-5580-a234-fbb26ab06aef', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 18, 18, 'to Abraham for a possession in the presence of the children of Heth, before all who went in at the gate of his city.'),
  ('420eb95d-6dd9-5aa5-a71d-a1a2b1db36fd', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 19, 19, 'After this, Abraham buried Sarah his wife in the cave of the field of Machpelah before Mamre (that is, Hebron), in the land of Canaan.'),
  ('f1368afc-f892-506a-a91e-ca8db7072fc5', 'fd163300-1a08-5eea-a463-f4a1fe9254b3', NULL, 20, 20, 'The field, and the cave that is in it, were deeded to Abraham for a possession of a burying place by the children of Heth.'),
  ('584c3770-776a-5839-af15-67b860420af6', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 1, 1, 'Abraham was old, and well stricken in age. Yahweh had blessed Abraham in all things.'),
  ('ec74d309-57a8-5df2-aef3-f6a113ddedfe', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 2, 2, 'Abraham said to his servant, the elder of his house, who ruled over all that he had, "Please put your hand under my thigh.'),
  ('6be1b894-07fa-5494-a546-f4f47a8604cd', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 3, 3, 'I will make you swear by Yahweh, the God of heaven and the God of the earth, that you shall not take a wife for my son of the daughters of the Canaanites, among whom I live.'),
  ('ddf96bed-2360-52af-a3a4-c06600a625a1', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 4, 4, 'But you shall go to my country, and to my relatives, and take a wife for my son Isaac."'),
  ('80beabc8-9d87-52c5-ad00-12f9bf248535', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 5, 5, 'The servant said to him, "What if the woman isn''t willing to follow me to this land? Must I bring your son again to the land you came from?"'),
  ('d0a4b88e-58da-5f51-a763-d62107090772', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 6, 6, 'Abraham said to him, "Beware that you don''t bring my son there again.'),
  ('978635cb-4b1f-56a0-a6fb-dc6839616cf8', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 7, 7, 'Yahweh, the God of heaven, who took me from my father''s house, and from the land of my birth, who spoke to me, and who swore to me, saying, ''I will give this land to your seed.'' He will send his angel before you, and you shall take a wife for my son from there.'),
  ('9de36902-e579-5ef7-aab5-956c22090477', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 8, 8, 'If the woman isn''t willing to follow you, then you shall be clear from this my oath. Only you shall not bring my son there again."'),
  ('fcceb2ee-b328-5e2a-ad03-1c2135b2d7df', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 9, 9, 'The servant put his hand under the thigh of Abraham his master, and swore to him concerning this matter.'),
  ('1bde37af-4b09-5278-a5a3-32173b45a906', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 10, 10, 'The servant took ten camels, of his master''s camels, and departed, having a variety of good things of his master''s with him. He arose, and went to Mesopotamia, to the city of Nahor.'),
  ('e664929b-7923-58a2-a78e-e6d09e9f801c', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 11, 11, 'He made the camels kneel down outside the city by the well of water at the time of evening, the time that women go out to draw water.'),
  ('cb37e31d-b623-5021-ae5c-2f3d6a618e53', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 12, 12, 'He said, "Yahweh, the God of my master Abraham, please give me success this day, and show kindness to my master Abraham.'),
  ('10842755-e19f-5af7-aec0-ebebd08a70f0', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 13, 13, 'Behold, I am standing by the spring of water. The daughters of the men of the city are coming out to draw water.'),
  ('714e95cd-6409-55c5-a60d-a76d86ef0e6c', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 14, 14, 'Let it happen, that the young lady to whom I will say, ''Please let down your pitcher, that I may drink,'' and she will say, ''Drink, and I will also give your camels a drink,''--let her be the one you have appointed for your servant Isaac. By this I will know that you have shown kindness to my master."'),
  ('41979848-1f00-52c8-ad22-cef311f0c379', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 15, 15, 'It happened, before he had finished speaking, that behold, Rebekah came out, who was born to Bethuel the son of Milcah, the wife of Nahor, Abraham''s brother, with her pitcher on her shoulder.'),
  ('43c37d75-3b58-5b7d-ab0e-80b7adf11de9', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 16, 16, 'The young lady was very beautiful to look at, a virgin, neither had any man known her. She went down to the spring, filled her pitcher, and came up.'),
  ('663e85f2-2263-501f-a2d4-e9b00b5dba11', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 17, 17, 'The servant ran to meet her, and said, "Please give me a drink, a little water from your pitcher."'),
  ('c015d027-a704-570c-a724-9d6b445d4164', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 18, 18, 'She said, "Drink, my lord." She hurried, and let down her pitcher on her hand, and gave him drink.'),
  ('20567e51-55ff-5df3-abba-8fddb749ea20', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 19, 19, 'When she had done giving him drink, she said, "I will also draw for your camels, until they have done drinking."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2fa18edc-6a18-524e-a6bf-db47e07b21bc', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 20, 20, 'She hurried, and emptied her pitcher into the trough, and ran again to the well to draw, and drew for all his camels.'),
  ('105309b2-9e30-592b-ab0d-3d09aade0c5e', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 21, 21, 'The man looked steadfastly at her, remaining silent, to know whether Yahweh had made his journey prosperous or not.'),
  ('a7f961ef-00e9-514f-ad18-d2e8276fee54', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 22, 22, 'It happened, as the camels had done drinking, that the man took a golden ring of half a shekel weight, and two bracelets for her hands of ten shekels weight of gold,'),
  ('25c0cf03-3610-5ef8-ac22-aeaba3528ee5', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 23, 23, 'and said, "Whose daughter are you? Please tell me. Is there room in your father''s house for us to lodge in?"'),
  ('d83b92a1-76cf-5d36-a2d5-b7a0264528f4', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 24, 24, 'She said to him, "I am the daughter of Bethuel the son of Milcah, whom she bore to Nahor."'),
  ('525d389c-5ea5-5854-a52a-8d4d1cd715a9', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 25, 25, 'She said moreover to him, "We have both straw and provender enough, and room to lodge in."'),
  ('b152edf5-1a37-5aec-a7cb-7868abead99f', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 26, 26, 'The man bowed his head, and worshiped Yahweh.'),
  ('afb93d12-25cf-5064-ad36-afb1ff2dfcbe', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 27, 27, 'He said, "Blessed be Yahweh, the God of my master Abraham, who has not forsaken his loving kindness and his truth toward my master. As for me, Yahweh has led me in the way to the house of my master''s relatives."'),
  ('0d6da2e5-d00e-52d9-a443-be7ba9624546', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 28, 28, 'The young lady ran, and told her mother''s house about these words.'),
  ('4bea46df-386d-593e-ab6f-64dbb1f7a3b0', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 29, 29, 'Rebekah had a brother, and his name was Laban. Laban ran out to the man, to the spring.'),
  ('eb4ee5b0-2710-5c8e-a008-d2b9d57ebcf8', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 30, 30, 'It happened, when he saw the ring, and the bracelets on his sister''s hands, and when he heard the words of Rebekah his sister, saying, "This is what the man said to me," that he came to the man. Behold, he was standing by the camels at the spring.'),
  ('287c4173-5eec-5e42-a579-e525aedf00c9', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 31, 31, 'He said, "Come in, you blessed of Yahweh. Why do you stand outside? For I have prepared the house, and room for the camels."'),
  ('08fc5e54-677c-5ae4-aba0-9f97aa72944c', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 32, 32, 'The man came into the house, and he unloaded the camels. He gave straw and provender for the camels, and water to wash his feet and the feet of the men who were with him.'),
  ('01608c5e-24c8-5104-ad8f-db673c986395', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 33, 33, 'Food was set before him to eat, but he said, "I will not eat until I have told my message." He said, "Speak on."'),
  ('eaf9ad84-2453-531c-a826-e3280abe7544', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 34, 34, 'He said, "I am Abraham''s servant.'),
  ('03432aa0-65db-5291-aa22-a737c6b33522', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 35, 35, 'Yahweh has blessed my master greatly. He has become great. He has given him flocks and herds, silver and gold, male servants and female servants, and camels and donkeys.'),
  ('fa5919bd-4196-5495-a5c5-5506e2c67d0d', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 36, 36, 'Sarah, my master''s wife, bore a son to my master when she was old. He has given all that he has to him.'),
  ('475f2c69-1e1d-5859-a798-8455d18fe106', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 37, 37, 'My master made me swear, saying, ''You shall not take a wife for my son of the daughters of the Canaanites, in whose land I live,'),
  ('cd51fc1f-e2fd-5e57-a6a5-b4a661c9c9e5', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 38, 38, 'but you shall go to my father''s house, and to my relatives, and take a wife for my son.'''),
  ('feb08ada-5638-5dc4-a85d-a079988ecfcf', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 39, 39, 'I asked my master, ''What if the woman will not follow me?'''),
  ('65578677-6810-5967-ad1f-c5bd506777f6', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 40, 40, 'He said to me, ''Yahweh, before whom I walk, will send his angel with you, and prosper your way. You shall take a wife for my son of my relatives, and of my father''s house.'),
  ('db66afbe-dd34-53ef-a587-f48a692c57c9', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 41, 41, 'Then will you be clear from my oath, when you come to my relatives. If they don''t give her to you, you shall be clear from my oath.'''),
  ('c6ea806b-409d-534b-aa17-ccf700aeec27', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 42, 42, 'I came this day to the spring, and said, ''Yahweh, the God of my master Abraham, if now you do prosper my way which I go--'),
  ('e6f8cdc8-0338-5609-a7ce-c6033fac3f43', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 43, 43, 'behold, I am standing by this spring of water. Let it happen, that the maiden who comes forth to draw, to whom I will say, "Please give me a little water from your pitcher to drink,"'),
  ('78964e60-1d2b-513d-ab61-773363ac3d88', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 44, 44, 'and she will tell me, "Drink, and I will also draw for your camels,"--let her be the woman whom Yahweh has appointed for my master''s son.'''),
  ('85f00f2f-ea89-5bef-aad8-0d7515660b94', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 45, 45, 'Before I had finished speaking in my heart, behold, Rebekah came forth with her pitcher on her shoulder. She went down to the spring, and drew. I said to her, ''Please let me drink.'''),
  ('bff2b806-0029-58f2-abf7-da872fa6cfde', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 46, 46, 'She hurried and let down her pitcher from her shoulder, and said, ''Drink, and I will also give your camels a drink.'' So I drank, and she also gave the camels a drink.'),
  ('a9ec0f82-d974-50ea-a62b-50310ec6edff', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 47, 47, 'I asked her, and said, ''Whose daughter are you?'' She said, ''The daughter of Bethuel, Nahor''s son, whom Milcah bore to him.'' I put the ring on her nose, and the bracelets on her hands.'),
  ('2a1f34aa-afa2-518f-a20c-407c8f9c18d6', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 48, 48, 'I bowed my head, and worshiped Yahweh, and blessed Yahweh, the God of my master Abraham, who had led me in the right way to take my master''s brother''s daughter for his son.'),
  ('04bdbe9e-10cf-5a31-a4bd-52ab5d86cb91', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 49, 49, 'Now if you will deal kindly and truly with my master, tell me. If not, tell me, that I may turn to the right hand, or to the left."'),
  ('9d38bf0f-15a4-57cb-a4a8-c8554ec76fdd', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 50, 50, 'Then Laban and Bethuel answered, "The thing proceeds from Yahweh. We can''t speak to you bad or good.'),
  ('7b441e13-930c-53a8-a65e-b398d259f661', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 51, 51, 'Behold, Rebekah is before you. Take her, and go, and let her be your master''s son''s wife, as Yahweh has spoken."'),
  ('22ca0057-19ce-5494-a058-7ef5c46fa1ec', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 52, 52, 'It happened that when Abraham''s servant heard their words, he bowed himself down to the earth to Yahweh.'),
  ('65be652d-a38c-5f7b-ac09-54fa49e65583', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 53, 53, 'The servant brought forth jewels of silver, and jewels of gold, and clothing, and gave them to Rebekah. He also gave precious things to her brother and her mother.'),
  ('52de7115-2467-51ab-a629-683277be124c', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 54, 54, 'They ate and drank, he and the men who were with him, and stayed all night. They rose up in the morning, and he said, "Send me away to my master."'),
  ('d6b5d71d-443a-513b-a7a4-1aec1f5ad89e', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 55, 55, 'Her brother and her mother said, "Let the young lady stay with us a few days, at least ten. After that she will go."'),
  ('1de950fe-84d7-50f9-acc2-91eea27a478e', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 56, 56, 'He said to them, "Don''t hinder me, since Yahweh has prospered my way. Send me away that I may go to my master."'),
  ('50dbc62f-f508-55df-a088-b030c1c389c5', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 57, 57, 'They said, "We will call the young lady, and ask her."'),
  ('eb2d4474-1af7-546c-a005-4fe9ccbfc3d1', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 58, 58, 'They called Rebekah, and said to her, "Will you go with this man?" She said, "I will go."'),
  ('cc458e32-5b27-5d8c-a6f0-abd064692535', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 59, 59, 'They sent away Rebekah, their sister, with her nurse, Abraham''s servant, and his men.'),
  ('6b0289cd-c30d-5c06-a252-522b8ee034d3', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 60, 60, 'They blessed Rebekah, and said to her, "Our sister, may you be the mother of thousands of ten thousands, and let your seed possess the gate of those who hate them."'),
  ('b4e9efb5-b894-566a-a69d-c4af5d7d6c86', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 61, 61, 'Rebekah arose with her ladies. They rode on the camels, and followed the man. The servant took Rebekah, and went his way.'),
  ('7791c198-6031-5f2d-af11-5c09d1854ade', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 62, 62, 'Isaac came from the way of Beer Lahai Roi, for he lived in the land of the South.'),
  ('dca2cc0f-f39d-5034-a29f-8e0a590ee0c7', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 63, 63, 'Isaac went out to meditate in the field at the evening. He lifted up his eyes, and saw, and, behold, there were camels coming.'),
  ('89a9a110-04da-5bde-a4b6-a21a87e9de6e', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 64, 64, 'Rebekah lifted up her eyes, and when she saw Isaac, she dismounted from the camel.'),
  ('fa176669-4eef-5673-a0d2-e17ed7a000c6', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 65, 65, 'She said to the servant, "Who is the man who is walking in the field to meet us?" The servant said, "It is my master." She took her veil, and covered herself.'),
  ('a3a35860-f49a-5638-ade5-aac00f804542', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 66, 66, 'The servant told Isaac all the things that he had done.'),
  ('e7f3a3be-deca-5577-ae83-334dd17dce5d', '25506d46-26a9-5b0e-a583-aed91a324627', NULL, 67, 67, 'Isaac brought her into his mother Sarah''s tent, and took Rebekah, and she became his wife. He loved her. Isaac was comforted after his mother''s death.'),
  ('2693ce0b-db66-5e49-a927-5516eb164f25', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 1, 1, 'Abraham took another wife, and her name was Keturah.'),
  ('cf112828-2ef2-58bd-a21d-8d8ec598256d', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 2, 2, 'She bore him Zimran, Jokshan, Medan, Midian, Ishbak, and Shuah.'),
  ('d752e42c-4959-55b5-ad13-58d80d4d8a6e', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 3, 3, 'Jokshan became the father of Sheba, and Dedan. The sons of Dedan were Asshurim, Letushim, and Leummim.'),
  ('f7bd2f95-ad25-50f4-a3a5-0a56b516f688', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 4, 4, 'The sons of Midian: Ephah, Epher, Hanoch, Abida, and Eldaah. All these were the children of Keturah.'),
  ('192865d5-3597-5e93-a771-ee10c7b8fecf', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 5, 5, 'Abraham gave all that he had to Isaac,'),
  ('46916d21-fd2a-5408-ad44-1f3916217e98', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 6, 6, 'but to the sons of Abraham''s concubines, Abraham gave gifts. He sent them away from Isaac his son, while he yet lived, eastward, to the east country.'),
  ('25c9e0f8-d7f0-5ddf-a3fe-c49c899c5087', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 7, 7, 'These are the days of the years of Abraham''s life which he lived: one hundred seventy-five years.'),
  ('2f7b953d-1e6d-536c-acc3-5040a65ac0c4', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 8, 8, 'Abraham gave up the spirit, and died in a good old age, an old man, and full of years, and was gathered to his people.'),
  ('dea852a4-b251-5fb0-a992-5877412e02ac', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 9, 9, 'Isaac and Ishmael, his sons, buried him in the cave of Machpelah, in the field of Ephron, the son of Zohar the Hittite, which is before Mamre,'),
  ('a367ae61-9ea7-57ca-a8a7-cbe28d3c2706', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 10, 10, 'the field which Abraham purchased of the children of Heth. Abraham was buried there with Sarah, his wife.'),
  ('19e81e51-e198-5fd5-a269-ae4d36e85677', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 11, 11, 'It happened after the death of Abraham that God blessed Isaac, his son. Isaac lived by Beer Lahai Roi.'),
  ('85fb11cc-59cf-5157-a999-d16f612b8a9b', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 12, 12, 'Now this is the history of the generations of Ishmael, Abraham''s son, whom Hagar the Egyptian, Sarah''s handmaid, bore to Abraham.'),
  ('4cb9d9f5-1471-568d-a643-8de40ce2c03b', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 13, 13, 'These are the names of the sons of Ishmael, by their names, according to the order of their birth: the firstborn of Ishmael, Nebaioth, then Kedar, Adbeel, Mibsam,'),
  ('1e0e95e6-b31a-5dba-aeea-320046a4f74c', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 14, 14, 'Mishma, Dumah, Massa,'),
  ('2c10a11f-9964-56c1-a04a-04f1d9a859ad', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 15, 15, 'Hadad, Tema, Jetur, Naphish, and Kedemah.'),
  ('e117d519-e743-59ec-a075-fdeb84616af5', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 16, 16, 'These are the sons of Ishmael, and these are their names, by their villages, and by their encampments: twelve princes, according to their nations.'),
  ('b74ac08c-0a0d-5f2b-aa2c-9feee6dcf2bd', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 17, 17, 'These are the years of the life of Ishmael: one hundred thirty-seven years. He gave up the spirit and died, and was gathered to his people.'),
  ('b3cf48e1-02a2-5c68-abb1-014938eb0d61', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 18, 18, 'They lived from Havilah to Shur that is before Egypt, as you go toward Assyria. He lived opposite all his relatives.'),
  ('bcd64208-bbc6-5dab-a19d-8b90eaadcea6', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 19, 19, 'This is the history of the generations of Isaac, Abraham''s son. Abraham became the father of Isaac.'),
  ('ee9c20b9-632c-5814-a0d1-b4eb68cd1f69', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 20, 20, 'Isaac was forty years old when he took Rebekah, the daughter of Bethuel the Syrian of Paddan Aram, the sister of Laban the Syrian, to be his wife.'),
  ('0889947c-b00e-57af-a552-db7533d66cc5', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 21, 21, 'Isaac entreated Yahweh for his wife, because she was barren. Yahweh was entreated by him, and Rebekah his wife conceived.'),
  ('3c50fbd9-7fb1-56e3-aaff-b9d0ead0d73b', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 22, 22, 'The children struggled together within her. She said, "If it be so, why do I live?" She went to inquire of Yahweh.'),
  ('82e470b9-40ef-5c65-a2e7-8a7726da0d03', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 23, 23, 'Yahweh said to her, "Two nations are in your womb. Two peoples will be separated from your body. The one people will be stronger than the other people. The elder will serve the younger."'),
  ('50c265f0-c05c-578a-a726-48dfa0c12e86', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 24, 24, 'When her days to be delivered were fulfilled, behold, there were twins in her womb.'),
  ('55b6dd9c-0e45-593f-ae90-82fdf3f21d95', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 25, 25, 'The first came out red all over, like a hairy garment. They named him Esau.'),
  ('dc44122d-0f90-5985-a644-a146df2e784c', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 26, 26, 'After that, his brother came out, and his hand had hold on Esau''s heel. He was named Jacob. Isaac was sixty years old when she bore them.'),
  ('a53dc01b-0d0f-52e8-ab7f-ebe48d3aee16', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 27, 27, 'The boys grew. Esau was a skillful hunter, a man of the field. Jacob was a quiet man, living in tents.'),
  ('e96885d5-4a1d-506d-aa5e-849e8a3a5f52', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 28, 28, 'Now Isaac loved Esau, because he ate his venison. Rebekah loved Jacob.'),
  ('57fc271c-5097-5c1e-a3b5-1037845c209e', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 29, 29, 'Jacob boiled stew. Esau came in from the field, and he was famished.'),
  ('62e083c7-0c45-574f-a16e-a74d43c1f0ae', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 30, 30, 'Esau said to Jacob, "Please feed me with that same red stew, for I am famished." Therefore his name was called Edom.'),
  ('42d8f4da-b752-5abd-adce-151993e49e09', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 31, 31, 'Jacob said, "First, sell me your birthright."'),
  ('a039ea2f-b912-5b56-acb1-fdf190ea6177', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 32, 32, 'Esau said, "Behold, I am about to die. What good is the birthright to me?"'),
  ('06f7f8d8-9b32-5f84-aa63-050cba7d3e94', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 33, 33, 'Jacob said, "Swear to me first." He swore to him. He sold his birthright to Jacob.'),
  ('1613c9ec-6fea-57e9-a5ff-2efa43db5a0c', 'a4b0cd91-f62e-5035-af38-fba804943b05', NULL, 34, 34, 'Jacob gave Esau bread and stew of lentils. He ate and drank, rose up, and went his way. So Esau despised his birthright.'),
  ('310648ee-3543-577d-a3a4-06be2d381e8a', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 1, 1, 'There was a famine in the land, besides the first famine that was in the days of Abraham. Isaac went to Abimelech king of the Philistines, to Gerar.'),
  ('3c806f70-2df4-5e31-a581-d6aaf14eb185', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 2, 2, 'Yahweh appeared to him, and said, "Don''t go down into Egypt. Live in the land I will tell you about.'),
  ('c96674c3-bdda-585f-a816-6ce36d75ec27', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 3, 3, 'Live in this land, and I will be with you, and will bless you. For to you, and to your seed, I will give all these lands, and I will establish the oath which I swore to Abraham your father.'),
  ('5b3c220a-fa80-5fe5-aeb6-72410b11ea87', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 4, 4, 'I will multiply your seed as the stars of the sky, and will give to your seed all these lands. In your seed will all the nations of the earth be blessed,'),
  ('b658f4e8-f171-538c-a753-77866fc3c77c', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 5, 5, 'because Abraham obeyed my voice, and kept my requirements, my commandments, my statutes, and my laws."'),
  ('23df381c-97ce-5b84-a977-7199b25dc4d0', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 6, 6, 'Isaac lived in Gerar.'),
  ('84688695-d62d-5218-acd1-e8e6607ea200', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 7, 7, 'The men of the place asked him about his wife. He said, "She is my sister," for he was afraid to say, "My wife," lest, he thought, "the men of the place might kill me for Rebekah, because she is beautiful to look at."'),
  ('b3c33474-442d-519e-aa19-624c10c9da32', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 8, 8, 'It happened, when he had been there a long time, that Abimelech king of the Philistines looked out at a window, and saw, and, behold, Isaac was caressing Rebekah, his wife.'),
  ('fc878174-ca34-5711-a988-355773cbcdc7', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 9, 9, 'Abimelech called Isaac, and said, "Behold, surely she is your wife. Why did you say, ''She is my sister?''" Isaac said to him, "Because I said, ''Lest I die because of her.''"'),
  ('f94809a0-e797-586e-a480-cb5141826a93', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 10, 10, 'Abimelech said, "What is this you have done to us? One of the people might easily have lain with your wife, and you would have brought guilt on us!"'),
  ('43be1793-d322-520c-aa2f-46821113bf8e', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 11, 11, 'Abimelech commanded all the people, saying, "He who touches this man or his wife will surely be put to death."'),
  ('1bf037f7-92fe-5c00-a185-593fa4bb4543', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 12, 12, 'Isaac sowed in that land, and reaped in the same year one hundred times what he planted. Yahweh blessed him.'),
  ('da603c13-9043-59a8-a8a9-d959069fabc7', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 13, 13, 'The man grew great, and grew more and more until he became very great.'),
  ('57ba9dff-b0e3-5ba3-a5ac-070f5dd19b94', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 14, 14, 'He had possessions of flocks, possessions of herds, and a great household. The Philistines envied him.'),
  ('8f7be750-5ad5-5125-ab29-d7f7b9c0b489', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 15, 15, 'Now all the wells which his father''s servants had dug in the days of Abraham his father, the Philistines had stopped, and filled with earth.'),
  ('887de13a-7658-56ca-a83e-85634b623ba2', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 16, 16, 'Abimelech said to Isaac, "Go from us, for you are much mightier than we."'),
  ('20791a83-af4f-5e0b-afde-7d7a42baff66', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 17, 17, 'Isaac departed from there, encamped in the valley of Gerar, and lived there.'),
  ('16defd8a-84bf-50a9-acd9-bd9e5522bce6', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 18, 18, 'Isaac dug again the wells of water, which they had dug in the days of Abraham his father. For the Philistines had stopped them after the death of Abraham. He called their names after the names by which his father had called them.'),
  ('128b353d-30a2-5611-a726-13224cbe866b', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 19, 19, 'Isaac''s servants dug in the valley, and found there a well of springing water.'),
  ('994c9b65-67f0-59f5-a89b-eb8a30def282', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 20, 20, 'The herdsmen of Gerar argued with Isaac''s herdsmen, saying, "The water is ours." He called the name of the well Esek, because they contended with him.'),
  ('143d4b83-293e-574b-a383-6b5982307e02', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 21, 21, 'They dug another well, and they argued over that, also. He called its name Sitnah.'),
  ('9bcd827b-44c6-5d48-a89d-2a14de0bb250', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 22, 22, 'He left that place, and dug another well. They didn''t argue over that one. He called it Rehoboth. He said, "For now Yahweh has made room for us, and we will be fruitful in the land."'),
  ('03a7f6d8-b941-5771-a697-c124a7e8991e', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 23, 23, 'He went up from there to Beersheba.'),
  ('a3b2bcfa-056d-5356-a777-855bf45142ae', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 24, 24, 'Yahweh appeared to him the same night, and said, "I am the God of Abraham your father. Don''t be afraid, for I am with you, and will bless you, and multiply your seed for my servant Abraham''s sake."'),
  ('e4c61f8c-28ef-5014-a8ae-8262b546b0d9', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 25, 25, 'He built an altar there, and called on the name of Yahweh, and pitched his tent there. There Isaac''s servants dug a well.'),
  ('1e4a8b63-6d26-5868-a88b-207710528cfb', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 26, 26, 'Then Abimelech went to him from Gerar, and Ahuzzath his friend, and Phicol the captain of his army.'),
  ('b6784a82-8a96-517e-aba7-b8265560d707', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 27, 27, 'Isaac said to them, "Why have you come to me, since you hate me, and have sent me away from you?"'),
  ('53014d16-b355-5964-a053-c4ea81b04997', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 28, 28, 'They said, "We saw plainly that Yahweh was with you. We said, ''Let there now be an oath between us, even between us and you, and let us make a covenant with you,'),
  ('6a3b733e-8af6-5097-a066-708faea9e42d', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 29, 29, 'that you will do us no harm, as we have not touched you, and as we have done to you nothing but good, and have sent you away in peace.'' You are now the blessed of Yahweh."'),
  ('d3eae4ae-70ff-527e-a44f-79cb4f810fe0', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 30, 30, 'He made them a feast, and they ate and drank.'),
  ('dacaa81b-8436-5933-a251-439b6590e4f8', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 31, 31, 'They rose up some time in the morning, and swore one to another. Isaac sent them away, and they departed from him in peace.'),
  ('e4c27c25-de49-5e08-a886-0f457f7566f6', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 32, 32, 'It happened the same day, that Isaac''s servants came, and told him concerning the well which they had dug, and said to him, "We have found water."'),
  ('52b33da6-59b3-5212-a64e-dd15d296d566', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 33, 33, 'He called it Shibah. Therefore the name of the city is Beersheba to this day.'),
  ('cf9005bb-0b6c-5d5a-a5b7-5d54989df6a6', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 34, 34, 'When Esau was forty years old, he took as wife Judith, the daughter of Beeri the Hittite, and Basemath, the daughter of Elon the Hittite.'),
  ('57e8d7ea-21bf-57ba-aa48-dcde020914b9', '04d8c227-e264-58db-a713-b37ce033ec04', NULL, 35, 35, 'They grieved Isaac''s and Rebekah''s spirits.'),
  ('e591dbd4-ac25-53b1-a610-a4797c07859e', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 1, 1, 'It happened, that when Isaac was old, and his eyes were dim, so that he could not see, he called Esau his elder son, and said to him, "My son?" He said to him, "Here I am."'),
  ('0c282a12-576b-5768-a28a-ef4c9b08e9f6', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 2, 2, 'He said, "See now, I am old. I don''t know the day of my death.'),
  ('aee71aa8-56f3-5be2-a247-aec02de07cb7', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 3, 3, 'Now therefore, please take your weapons, your quiver and your bow, and go out to the field, and take me venison.'),
  ('74014f71-b0d5-5fcf-a3be-a70cfedd5112', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 4, 4, 'Make me savory food, such as I love, and bring it to me, that I may eat, and that my soul may bless you before I die."'),
  ('4e9e0b7d-91ab-530e-afc2-484e4103f7b6', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 5, 5, 'Rebekah heard when Isaac spoke to Esau his son. Esau went to the field to hunt for venison, and to bring it.'),
  ('1eab392a-6306-58b6-aca9-3a01baf37c3c', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 6, 6, 'Rebekah spoke to Jacob her son, saying, "Behold, I heard your father speak to Esau your brother, saying,'),
  ('d0ccf9eb-9493-5ce9-a04c-5931b33e4e5e', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 7, 7, '''Bring me venison, and make me savory food, that I may eat, and bless you before Yahweh before my death.'''),
  ('0014cd0d-022b-574c-a6b9-241e08448ff4', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 8, 8, 'Now therefore, my son, obey my voice according to that which I command you.'),
  ('92aaa675-c452-5423-aa42-4101d9d7482d', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 9, 9, 'Go now to the flock, and get me from there two good young goats. I will make them savory food for your father, such as he loves.'),
  ('82a0b33d-ee0c-50c4-a9f4-40b060a3a304', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 10, 10, 'You shall bring it to your father, that he may eat, so that he may bless you before his death."'),
  ('6b38a2aa-e00a-5a16-a804-347ffa80ef63', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 11, 11, 'Jacob said to Rebekah his mother, "Behold, Esau my brother is a hairy man, and I am a smooth man.'),
  ('2c1ba6f2-2f0e-5166-ac28-59630c6b3c5c', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 12, 12, 'What if my father touches me? I will seem to him as a deceiver, and I would bring a curse on myself, and not a blessing."'),
  ('cb6a27b0-5fa4-5d74-ab06-faa7a3e5e099', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 13, 13, 'His mother said to him, "Let your curse be on me, my son. Only obey my voice, and go get them for me."'),
  ('7ccc9c90-dfc3-59be-a004-b93917a45660', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 14, 14, 'He went, and got them, and brought them to his mother. His mother made savory food, such as his father loved.'),
  ('3cc4dea9-bc51-540f-a444-5481024a4f7b', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 15, 15, 'Rebekah took the good clothes of Esau, her elder son, which were with her in the house, and put them on Jacob, her younger son.'),
  ('e5c9e097-d103-5f46-ae51-5a0633e8ef3c', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 16, 16, 'She put the skins of the young goats on his hands, and on the smooth of his neck.'),
  ('97649695-e133-5195-a80b-fa26a64b0d4a', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 17, 17, 'She gave the savory food and the bread, which she had prepared, into the hand of her son Jacob.'),
  ('9f1201f6-3bed-5066-a04a-a2fc2512578c', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 18, 18, 'He came to his father, and said, "My father?" He said, "Here I am. Who are you, my son?"'),
  ('654b6017-5c24-566c-a4b0-3a72840ca798', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 19, 19, 'Jacob said to his father, "I am Esau your firstborn. I have done what you asked me to do. Please arise, sit and eat of my venison, that your soul may bless me."'),
  ('b801c865-bc20-5fb7-aab1-3c8b68b392db', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 20, 20, 'Isaac said to his son, "How is it that you have found it so quickly, my son?" He said, "Because Yahweh your God gave me success."'),
  ('57346025-330e-518b-a49b-5606e508ca39', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 21, 21, 'Isaac said to Jacob, "Please come near, that I may feel you, my son, whether you are really my son Esau or not."'),
  ('23da84e4-5042-5af0-af07-f384a7982163', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 22, 22, 'Jacob went near to Isaac his father. He felt him, and said, "The voice is Jacob''s voice, but the hands are the hands of Esau."'),
  ('14f7d496-1821-5883-a6ea-fa92acc3c899', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 23, 23, 'He didn''t recognize him, because his hands were hairy, like his brother, Esau''s hands. So he blessed him.'),
  ('9dbde1ee-52d4-564c-a50b-56740ef8347c', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 24, 24, 'He said, "Are you really my son Esau?" He said, "I am."'),
  ('442abd0d-6fd6-5da8-ac03-3029106bc426', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 25, 25, 'He said, "Bring it near to me, and I will eat of my son''s venison, that my soul may bless you." He brought it near to him, and he ate. He brought him wine, and he drank.'),
  ('61b3887d-63d6-5672-a531-9e2efa90a77f', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 26, 26, 'His father Isaac said to him, "Come near now, and kiss me, my son."'),
  ('c4902dbd-3479-5020-a41b-58bdb4f096af', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 27, 27, 'He came near, and kissed him. He smelled the smell of his clothing, and blessed him, and said, "Behold, the smell of my son is as the smell of a field which Yahweh has blessed.'),
  ('ad5a0944-ca96-5d1c-a731-67975723013f', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 28, 28, 'God give you of the dew of the sky, of the fatness of the earth, and plenty of grain and new wine.'),
  ('05a3f000-1a88-5a1b-a47f-d8d72a5fe17a', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 29, 29, 'Let peoples serve you, and nations bow down to you. Be lord over your brothers. Let your mother''s sons bow down to you. Cursed be everyone who curses you. Blessed be everyone who blesses you."'),
  ('7ef6b144-a0fe-55c9-a5bc-d1ef0f18230d', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 30, 30, 'It happened, as soon as Isaac had made an end of blessing Jacob, and Jacob had just gone out from the presence of Isaac his father, that Esau his brother came in from his hunting.'),
  ('584442a1-0ebc-59fa-aa7f-9ce7d6b5cf98', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 31, 31, 'He also made savory food, and brought it to his father. He said to his father, "Let my father arise, and eat of his son''s venison, that your soul may bless me."'),
  ('c75d3fc4-7f0b-521d-a687-b2216f4c4ccd', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 32, 32, 'Isaac his father said to him, "Who are you?" He said, "I am your son, your firstborn, Esau."'),
  ('2f7f31d3-f0bf-5f4a-a865-1af3d69df3df', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 33, 33, 'Isaac trembled violently, and said, "Who, then, is he who has taken venison, and brought it me, and I have eaten of all before you came, and have blessed him? Yes, he will be blessed."'),
  ('ebba8c30-ab39-5fac-a112-a4b0fa6eb4c4', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 34, 34, 'When Esau heard the words of his father, he cried with an exceeding great and bitter cry, and said to his father, "Bless me, even me also, my father."'),
  ('0f7df47d-1e0a-5595-a48f-6ad31fe3ee7b', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 35, 35, 'He said, "Your brother came with deceit, and has taken away your blessing."'),
  ('ee9a0e9c-2b40-5153-a2d9-dbeffa994e36', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 36, 36, 'He said, "Isn''t he rightly named Jacob? For he has supplanted me these two times. He took away my birthright. See, now he has taken away my blessing." He said, "Haven''t you reserved a blessing for me?"'),
  ('4c3739a7-104f-5e5d-a095-ae2ba977db34', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 37, 37, 'Isaac answered Esau, "Behold, I have made him your lord, and all his brothers have I given to him for servants. With grain and new wine have I sustained him. What then will I do for you, my son?"'),
  ('de1d4f76-fb16-5abb-a67a-db6e1f07082a', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 38, 38, 'Esau said to his father, "Have you but one blessing, my father? Bless me, even me also, my father." Esau lifted up his voice, and wept.'),
  ('8d9418b9-18e7-5844-a304-2ea03aa09e59', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 39, 39, 'Isaac his father answered him, "Behold, of the fatness of the earth will be your dwelling, and of the dew of the sky from above.'),
  ('297b2bc0-fa72-50cd-a666-3f58016cd9a0', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 40, 40, 'By your sword will you live, and you will serve your brother. It will happen, when you will break loose, that you shall shake his yoke from off your neck."'),
  ('d0fe73e1-5813-5864-af8c-84911cf014cb', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 41, 41, 'Esau hated Jacob because of the blessing with which his father blessed him. Esau said in his heart, "The days of mourning for my father are at hand. Then I will kill my brother Jacob."'),
  ('a41e168e-85a7-53ad-af5e-66244ce4c96f', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 42, 42, 'The words of Esau, her elder son, were told to Rebekah. She sent and called Jacob, her younger son, and said to him, "Behold, your brother Esau comforts himself about you by planning to kill you.'),
  ('48988e00-79ce-5d10-acd5-5d792099ed3b', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 43, 43, 'Now therefore, my son, obey my voice. Arise, flee to Laban, my brother, in Haran.'),
  ('fb9ed135-7a91-56e7-a2ab-1fab592ee5cf', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 44, 44, 'Stay with him a few days, until your brother''s fury turns away;'),
  ('84ada0e6-caaa-53e0-a417-259ebe88bbe2', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 45, 45, 'until your brother''s anger turn away from you, and he forgets what you have done to him. Then I will send, and get you from there. Why should I be bereaved of you both in one day?"'),
  ('10cdb6a1-64cf-5c5f-a3d0-8f822578aace', '3680f6de-900b-5e1a-a8e4-5eca03efcec0', NULL, 46, 46, 'Rebekah said to Isaac, "I am weary of my life because of the daughters of Heth. If Jacob takes a wife of the daughters of Heth, such as these, of the daughters of the land, what good will my life do me?"'),
  ('2a60ed21-ac18-5221-a1b6-75f17de729c3', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 1, 1, 'Isaac called Jacob, blessed him, and commanded him, "You shall not take a wife of the daughters of Canaan.'),
  ('656b7e4a-64cc-573a-a755-f19b3fb76cd6', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 2, 2, 'Arise, go to Paddan Aram, to the house of Bethuel your mother''s father. Take a wife from there from the daughters of Laban, your mother''s brother.'),
  ('d2760b08-dbfd-5656-aa6c-e1f8e0dafbbb', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 3, 3, 'May God Almighty bless you, and make you fruitful, and multiply you, that you may be a company of peoples,'),
  ('7d18fc2b-e356-5ab6-ab29-c195e3e307c7', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 4, 4, 'and give you the blessing of Abraham, to you, and to your seed with you, that you may inherit the land where you travel, which God gave to Abraham."'),
  ('f78789e9-c39b-577e-aaf5-78d3ae196b35', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 5, 5, 'Isaac sent Jacob away. He went to Paddan Aram to Laban, son of Bethuel the Syrian, Rebekah''s brother, Jacob''s and Esau''s mother.'),
  ('b5de90cb-3f46-51d6-a8a1-5c116534c294', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 6, 6, 'Now Esau saw that Isaac had blessed Jacob and sent him away to Paddan Aram, to take him a wife from there, and that as he blessed him he gave him a command, saying, "You shall not take a wife of the daughters of Canaan,"'),
  ('4d59837e-733f-5aa7-ae2f-d141854f1da2', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 7, 7, 'and that Jacob obeyed his father and his mother, and was gone to Paddan Aram.'),
  ('16efecee-3c61-5181-a0c4-e73042279b21', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 8, 8, 'Esau saw that the daughters of Canaan didn''t please Isaac, his father.'),
  ('0ef86e43-0e32-5cc9-a50e-2cdefe46fe3a', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 9, 9, 'Esau went to Ishmael, and took, besides the wives that he had, Mahalath the daughter of Ishmael, Abraham''s son, the sister of Nebaioth, to be his wife.'),
  ('3385aad4-986d-5157-a8c4-8d953dcc2851', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 10, 10, 'Jacob went out from Beersheba, and went toward Haran.'),
  ('facd3dd4-de2d-51fb-a744-becde6fd7250', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 11, 11, 'He came to a certain place, and stayed there all night, because the sun had set. He took one of the stones of the place, and put it under his head, and lay down in that place to sleep.'),
  ('c63da784-e017-5fc2-aef2-6fdb900106fe', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 12, 12, 'He dreamed. Behold, a stairway set upon the earth, and its top reached to heaven. Behold, the angels of God ascending and descending on it.'),
  ('d1aae490-10f6-50c9-a0cf-d2bdad6e21d2', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 13, 13, 'Behold, Yahweh stood above it, and said, "I am Yahweh, the God of Abraham your father, and the God of Isaac. The land whereon you lie, to you will I give it, and to your seed.'),
  ('df012598-ff1d-5e67-a005-36510be6ab1d', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 14, 14, 'Your seed will be as the dust of the earth, and you will spread abroad to the west, and to the east, and to the north, and to the south. In you and in your seed will all the families of the earth be blessed.'),
  ('e7902ddb-b036-5e20-a75c-d68cc13d9258', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 15, 15, 'Behold, I am with you, and will keep you, wherever you go, and will bring you again into this land. For I will not leave you, until I have done that which I have spoken of to you."'),
  ('74e2fc59-aea5-5879-a272-5a136f90d500', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 16, 16, 'Jacob awakened out of his sleep, and he said, "Surely Yahweh is in this place, and I didn''t know it."'),
  ('2fec8c6d-1bb9-59a0-a437-48c98d5c417e', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 17, 17, 'He was afraid, and said, "How dreadful is this place! This is none other than God''s house, and this is the gate of heaven."'),
  ('d0df9bcf-e0a4-5cce-a5b4-742a0c86f0d5', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 18, 18, 'Jacob rose up early in the morning, and took the stone that he had put under his head, and set it up for a pillar, and poured oil on its top.'),
  ('43ec56a0-79d9-577c-abb0-4d36c5f8747e', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 19, 19, 'He called the name of that place Bethel, but the name of the city was Luz at the first.'),
  ('add19f08-920c-532a-ab56-1922db4f3793', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 20, 20, 'Jacob vowed a vow, saying, "If God will be with me, and will keep me in this way that I go, and will give me bread to eat, and clothing to put on,'),
  ('1bf71255-0e2c-577a-a4d7-dc9bfedcbee2', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 21, 21, 'so that I come again to my father''s house in peace, and Yahweh will be my God,'),
  ('fd8748b3-d97f-5259-a1e8-78dfc6a2189d', 'cc07d004-a583-5aa5-ac26-f6e1ac39276b', NULL, 22, 22, 'then this stone, which I have set up for a pillar, will be God''s house. Of all that you will give me I will surely give the tenth to you."'),
  ('3b5cfb5c-975c-52cc-abb6-bb5699045aa8', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 1, 1, 'Then Jacob went on his journey, and came to the land of the children of the east.'),
  ('b2d1dc7a-32b7-50aa-affa-840b4eb5f53e', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 2, 2, 'He looked, and behold, a well in the field, and, behold, three flocks of sheep lying there by it. For out of that well they watered the flocks. The stone on the well''s mouth was large.'),
  ('c05079d6-d02d-5b9e-ac98-50c3afbcc15a', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 3, 3, 'There all the flocks were gathered. They rolled the stone from the well''s mouth, and watered the sheep, and put the stone again on the well''s mouth in its place.'),
  ('4d64ffd3-5653-56b0-a3ed-6b266cf424aa', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 4, 4, 'Jacob said to them, "My relatives, where are you from?" They said, "We are from Haran."'),
  ('ab2fe2be-dd38-5c81-a5f1-90afe5a1da2c', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 5, 5, 'He said to them, "Do you know Laban, the son of Nahor?" They said, "We know him."'),
  ('f88f52a5-13fa-55b8-a5cc-958feeac3efa', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 6, 6, 'He said to them, "Is it well with him?" They said, "It is well. See, Rachel, his daughter, is coming with the sheep."'),
  ('8c3e1de4-1e5a-51fc-a063-d28c01eac78c', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 7, 7, 'He said, "Behold, it is still the middle of the day, not time to gather the livestock together. Water the sheep, and go and feed them."'),
  ('1ceea980-bf08-595c-aac4-07b12f223c95', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 8, 8, 'They said, "We can''t, until all the flocks are gathered together, and they roll the stone from the well''s mouth. Then we water the sheep."'),
  ('5162efdd-7331-5165-aa7d-9e4a65cd55ee', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 9, 9, 'While he was yet speaking with them, Rachel came with her father''s sheep, for she kept them.'),
  ('dec00281-4111-5b68-a6f2-44326bb80ebc', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 10, 10, 'It happened, when Jacob saw Rachel the daughter of Laban, his mother''s brother, and the sheep of Laban, his mother''s brother, that Jacob went near, and rolled the stone from the well''s mouth, and watered the flock of Laban his mother''s brother.'),
  ('d48191b8-30c4-5874-a904-d9ce966b26b7', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 11, 11, 'Jacob kissed Rachel, and lifted up his voice, and wept.'),
  ('35e7c188-3833-55dc-a063-1426dbfecae2', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 12, 12, 'Jacob told Rachel that he was her father''s brother, and that he was Rebekah''s son. She ran and told her father.'),
  ('e245c3ff-b242-562e-a680-f2126d5f5218', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 13, 13, 'It happened, when Laban heard the news of Jacob, his sister''s son, that he ran to meet Jacob, and embraced him, and kissed him, and brought him to his house. Jacob told Laban all these things.'),
  ('555d659d-5aeb-5b6c-af50-5449db5b134f', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 14, 14, 'Laban said to him, "Surely you are my bone and my flesh." He lived with him for a month.'),
  ('c33a874a-c5b4-5846-a6da-64639323f398', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 15, 15, 'Laban said to Jacob, "Because you are my brother, should you therefore serve me for nothing? Tell me, what will your wages be?"'),
  ('0d433414-7621-5d51-a387-47e80262045e', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 16, 16, 'Laban had two daughters. The name of the elder was Leah, and the name of the younger was Rachel.'),
  ('8e7a23d9-ad9f-56ca-af2a-cb2ac93cab07', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 17, 17, 'Leah''s eyes were weak, but Rachel was beautiful in form and attractive.'),
  ('426a0169-0c54-57f2-ada8-22e1236b7215', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 18, 18, 'Jacob loved Rachel. He said, "I will serve you seven years for Rachel, your younger daughter."'),
  ('88711fd2-392d-5d14-a922-ccb96f8af471', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 19, 19, 'Laban said, "It is better that I give her to you, than that I should give her to another man. Stay with me."'),
  ('cb1cf40d-1f1a-5c41-a30a-5b15fa059251', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 20, 20, 'Jacob served seven years for Rachel. They seemed to him but a few days, for the love he had for her.'),
  ('e9d6c6e6-eee0-5bec-acfc-578c4d01e8ec', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 21, 21, 'Jacob said to Laban, "Give me my wife, for my days are fulfilled, that I may go in to her."'),
  ('0a4ca89b-7c4e-5be2-a0b7-e7f144c30f31', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 22, 22, 'Laban gathered together all the men of the place, and made a feast.'),
  ('96b893a2-9f5e-55d9-ae9b-a6f17be3c103', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 23, 23, 'It happened in the evening, that he took Leah his daughter, and brought her to him. He went in to her.'),
  ('fd468ddd-7411-52cd-a130-53588074c2b2', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 24, 24, 'Laban gave Zilpah his handmaid to his daughter Leah for a handmaid.'),
  ('f735191f-7cbc-5884-a815-8e26a96195ea', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 25, 25, 'It happened in the morning that, behold, it was Leah. He said to Laban, "What is this you have done to me? Didn''t I serve with you for Rachel? Why then have you deceived me?"'),
  ('0851071f-7543-50e6-a6c9-df166015b507', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 26, 26, 'Laban said, "It is not done so in our place, to give the younger before the firstborn.'),
  ('ff236ee7-5142-5840-ae6b-f97f79c0b5ff', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 27, 27, 'Fulfill the week of this one, and we will give you the other also for the service which you will serve with me yet seven other years."'),
  ('1988ac14-ef1d-55cb-a898-555a1eac68c7', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 28, 28, 'Jacob did so, and fulfilled her week. He gave him Rachel his daughter as wife.'),
  ('59f55c3e-79c7-548a-af7e-1a2b5aedf2f1', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 29, 29, 'Laban gave to Rachel his daughter Bilhah, his handmaid, to be her handmaid.'),
  ('9ec79282-bf85-5583-a777-8cc0a5471fa0', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 30, 30, 'He went in also to Rachel, and he loved also Rachel more than Leah, and served with him yet seven other years.'),
  ('162c0a05-e4d6-5eac-a475-2b8e59b25ff7', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 31, 31, 'Yahweh saw that Leah was hated, and he opened her womb, but Rachel was barren.'),
  ('e41dd233-a5b9-5edb-acac-ca2ac3a8c608', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 32, 32, 'Leah conceived, and bore a son, and she named him Reuben. For she said, "Because Yahweh has looked at my affliction. For now my husband will love me."'),
  ('b9aaaee3-c1be-537a-ac55-54e91b6e2014', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 33, 33, 'She conceived again, and bore a son, and said, "Because Yahweh has heard that I am hated, he has therefore given me this son also." She named him Simeon.'),
  ('8cd7a4e8-9b8b-5ada-a317-e9d978cadc0d', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 34, 34, 'She conceived again, and bore a son. Said, "Now this time will my husband be joined to me, because I have borne him three sons." Therefore was his name called Levi.'),
  ('d91de5bf-bd04-5f7f-a6b5-719159d1a932', '12db04b6-1eb1-530b-ab37-bb5573a7e678', NULL, 35, 35, 'She conceived again, and bore a son. She said, "This time will I praise Yahweh." Therefore she named him Judah. Then she stopped bearing.'),
  ('db2c3ee2-78ec-55a4-a2a0-6cc859362a03', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 1, 1, 'When Rachel saw that she bore Jacob no children, Rachel envied her sister. She said to Jacob, "Give me children, or else I will die."'),
  ('25ebf571-ae44-5734-ad14-5d402b70ba16', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 2, 2, 'Jacob''s anger was kindled against Rachel, and he said, "Am I in God''s place, who has withheld from you the fruit of the womb?"'),
  ('4bdf0275-62ec-5793-a3fa-1bb1f51a89e3', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 3, 3, 'She said, "Behold, my maid Bilhah. Go in to her, that she may bear on my knees, and I also may obtain children by her."'),
  ('45889ce9-5890-5055-a64a-d374813fb2c9', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 4, 4, 'She gave him Bilhah her handmaid as wife, and Jacob went in to her.'),
  ('d5c17e3f-4a44-522e-a962-35cfd03d62cd', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 5, 5, 'Bilhah conceived, and bore Jacob a son.'),
  ('503769bf-f87e-5878-a9ac-8103c0759c6c', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 6, 6, 'Rachel said, "God has judged me, and has also heard my voice, and has given me a son." Therefore called she his name Dan.'),
  ('2dae6030-03a3-5039-a1ba-2cbfc5f9027c', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 7, 7, 'Bilhah, Rachel''s handmaid, conceived again, and bore Jacob a second son.'),
  ('ee91b921-83b5-58c2-acd7-c0b1e9f14291', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 8, 8, 'Rachel said, "With mighty wrestlings have I wrestled with my sister, and have prevailed." She named him Naphtali.'),
  ('39595ee3-65c9-5569-aa0f-5667f321b947', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 9, 9, 'When Leah saw that she had finished bearing, she took Zilpah, her handmaid, and gave her to Jacob as a wife.'),
  ('a56f5daf-0ada-5992-a439-88b5fdcb81b3', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 10, 10, 'Zilpah, Leah''s handmaid, bore Jacob a son.'),
  ('54b7ea15-c253-549d-aa14-c72f8444ef45', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 11, 11, 'Leah said, "How fortunate!" She named him Gad.'),
  ('5572ee7e-48ea-5c11-a0ed-14c9b32a2e04', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 12, 12, 'Zilpah, Leah''s handmaid, bore Jacob a second son.'),
  ('a22a1d8d-4d75-5d66-a89d-3fcfaac6c15d', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 13, 13, 'Leah said, "Happy am I, for the daughters will call me happy." She named him Asher.'),
  ('bf3bf514-75ef-5c1c-a47f-606de558a396', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 14, 14, 'Reuben went in the days of wheat harvest, and found mandrakes in the field, and brought them to his mother, Leah. Then Rachel said to Leah, "Please give me some of your son''s mandrakes."'),
  ('b5187f43-3b8a-586c-a79f-8058e00a5129', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 15, 15, 'She said to her, "Is it a small matter that you have taken away my husband? Would you take away my son''s mandrakes, also?" Rachel said, "Therefore he will lie with you tonight for your son''s mandrakes."'),
  ('08d8128f-f42d-5a6f-ab37-c412d5058255', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 16, 16, 'Jacob came from the field in the evening, and Leah went out to meet him, and said, "You must come in to me; for I have surely hired you with my son''s mandrakes." He lay with her that night.'),
  ('73488aec-77ed-5cbd-a2cf-d88dd2139b4f', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 17, 17, 'God listened to Leah, and she conceived, and bore Jacob a fifth son.'),
  ('effaa6b8-901a-53c0-aa11-6588a743161f', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 18, 18, 'Leah said, "God has given me my hire, because I gave my handmaid to my husband." She named him Issachar.'),
  ('8a23a7ea-a94a-5b98-a1f0-45d335706d55', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 19, 19, 'Leah conceived again, and bore a sixth son to Jacob.'),
  ('96dff7c6-42b3-5be1-ad2e-aec67ef6e1e6', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 20, 20, 'Leah said, "God has endowed me with a good dowry. Now my husband will live with me, because I have borne him six sons." She named him Zebulun.'),
  ('7ccfa924-f9f0-5612-a2d9-40d8c7b145ab', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 21, 21, 'Afterwards, she bore a daughter, and named her Dinah.'),
  ('647dbcbb-33e4-55ef-aac5-f67197a9860e', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 22, 22, 'God remembered Rachel, and God listened to her, and opened her womb.'),
  ('f37b5523-dc5c-5d4c-ac78-a747c36398d8', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 23, 23, 'She conceived, bore a son, and said, "God has taken away my reproach."'),
  ('900d6bd3-d321-5941-a62f-ad883cf8d814', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 24, 24, 'She named him Joseph, saying, "May Yahweh add another son to me."'),
  ('f63c1270-0c84-5261-a717-b5d757c17994', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 25, 25, 'It happened, when Rachel had borne Joseph, that Jacob said to Laban, "Send me away, that I may go to my own place, and to my country.'),
  ('1606da23-2f12-5aa6-a097-93cdd27668a5', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 26, 26, 'Give me my wives and my children for whom I have served you, and let me go; for you know my service with which I have served you."'),
  ('c34b5cb0-01bb-5008-a8ab-ea36375b3a89', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 27, 27, 'Laban said to him, "If now I have found favor in your eyes, stay here, for I have divined that Yahweh has blessed me for your sake."'),
  ('550e86fe-1c87-5f41-ae5e-bcfb1ed68cc8', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 28, 28, 'He said, "Appoint me your wages, and I will give it."'),
  ('713795d4-2711-559c-a228-a80a5f5b72aa', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 29, 29, 'He said to him, "You know how I have served you, and how your livestock have fared with me.'),
  ('09384664-01ee-565e-aa26-25bf8a8582a8', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 30, 30, 'For it was little which you had before I came, and it has increased to a multitude. Yahweh has blessed you wherever I turned. Now when will I provide for my own house also?"')
